WITH payload AS (SELECT $archive_payload$[{"id":"db48a7e3-08cb-5a71-84f5-626602039eb1","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -طلب إبطال عقد بيع -حقيقة املنازعة تعرض يف حيازة - املدعى عليه ليس ذو صفة يف الدعوى -سلطة القاضي يف تكييف الدعوى -طلب وقف دعوى عن ذات املوضوع منظورة يف محكمة أخرى -احلكم بصرف النظر وإفهام املدعي بإقامة الدعوى على من تعرض له باحليازة .","document_number":"34284029","case_number":"34297925","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجازان وبن احملالة لنا","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/30","year":"1434","subject":"بيع -طلب إبطال عقد بيع -حقيقة املنازعة تعرض يف حيازة - املدعى عليه ليس ذو صفة يف الدعوى -سلطة القاضي يف تكييف الدعوى -طلب وقف دعوى عن ذات املوضوع منظورة يف محكمة أخرى -احلكم بصرف النظر وإفهام املدعي بإقامة الدعوى على من تعرض له باحليازة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/30 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34284029 :‬‬\n                         ‫َر ْق ُم الدعوى‪34297925 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34349102‬تاريخه‪1434/11/4 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬طلــب إبطــال عقــد بيــع ‪ -‬حقيقــة املنازعــة تعــرض يف حيــازة ‪-‬‬\n      ‫املدعــى عليــه ليــس ذو صفــة يف الدعــوى ‪ -‬ســلطة القاضــي يف تكييــف‬\n      ‫الدعــوى ‪ -‬طلــب وقــف دعــوى عــن ذات املوضــوع منظــورة يف محكمــة‬\n      ‫أخــرى ‪ -‬احلكــم بصــرف النظــر وإفهــام املدعــي بإقامــة الدعــوى علــى‬\n                                                     ‫مــن تعــرض لــه باحليــازة ‪.‬‬\n\n\n\n\n      ‫الفقــرة الثانيــة مــن املــادة الرابعــة مــن نظــام املرافعــات الشــرعية ونصهــا‬\n      ‫(يســتظهر القاضــي الطلــب إن لــم يحــرره طالبــه ويــرد مــا ال مصلحــة‬\n                                   ‫فيــه ســواء أكان الطلــب أصليـ ًا أو عارضـ ًا) ‪.‬‬\n\n\n\n\n      ‫أقــام املدعــي دعــواه ضــد املدعــى عليــه مطالبـ ًا احلكــم بإبطــال عقــد بيع‬\n      ‫مزعــوم وجــوده بــن املدعــى عليــه وشــخص ثالــث غيــر ممثــل يف الدعــوى‬\n      ‫‪ ،‬مبوجبــة بــاع املدعــى عليــه للشــخص الثالــث أرضـ ًا هــي ملــك للمدعــي‬\n      ‫‪ ،‬ومبواجهــة املدعــى عليــه وكالــة بذلــك طلــب التأجيــل للــرد وتخلــف‬\n      ‫عــن ذلــك ‪ ،‬وبســؤال املدعــى هــل تعــرض لــك املدعــى عليــه يف حيازتــك‬\n      ‫أجــاب ب ـ (ال) ولكنــه باعهــا وهــو غيــر مالــك إلــى شــخص ثالــث ينازعني‬\n      ‫يف حيازتــي و أقــام دعــوى ضــدي طلبــت إيقافهــا لكونــي أقمــت الدعــوى‬\n\n‫‪265‬‬\n\f‫املاثلــة ‪ ،‬ونظــر ًا ألن املدعــى عليــه لــم يتعــرض للمدعــي يف حيازتــه وال‬\n‫وضــع يــده وأن التعــرض مــن شــخص ثالــث هــو مــن تكــون مصلحــة‬\n‫املدعــي يف اختصامــه بحســبان أنــه املتعــرض لــه يف حيازتــه ‪ ،‬لذلــك‬\n‫قــررت احملكمــة صــرف النظــر عــن الدعــوى ‪ ،‬وقــد اعتــرض املدعــي‬\n             ‫علــى احلكــم وجــرى التصديــق مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬أمــا بعــد‬\n‫ـاء علــى املعاملــة‬\n                   ‫فلــدي أنــا ‪ .........‬القاضــي باحملكمــة العامــة بجــازان وبنـ ً‬\n‫احملالــة لنــا مــن فضيلــة القائــم بعمــل رئيــس احملكمــة العامــة بجــازان‬\n‫برقــم ‪ 34297925‬وتاريــخ ‪ 1434/06/27‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 341563704‬وتاريخ ‪ 1434/06/27‬هـ ففي يوم السبت ‪1434/07/22‬‬\n‫ه ـ افتتحــت اجللســة وفيهــا حضــر ‪.........‬ســعودي اجلنســية يحمــل الســجل‬\n‫ا عــن ‪.........‬ســعودي اجلنســية يحمــل‬       ‫املدنــي رقــم ‪.........‬بصفتــه وكي ـ ً‬\n‫الســجل املدنــي رقــم ‪.........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n‫محافظــة خميــس مشــيط برقــم ‪ 34824623‬وتاريــخ ‪1434/06/27‬ه ـ‬\n‫املخــول لــه فيهــا حــق املطالبــة وإقامــة الدعــاوى واملرافعــة واملدافعــة‬\n‫وســماع الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح وطلــب‬\n‫اليمــن ورده واالمتنــاع عنــه وإحضــار الشــهود والبينــات والطعــن فيهــا‬\n‫وطلــب التحكيــم واملطالبــة بتنفيــذ األحــكام وقبــول األحــكام‬\n‫ونفيهــا واالعتــراض علــى األحــكام وطلــب االســتئناف وإنهــا ء مــا يلــزم‬\n‫حضــور اجللســات يف جميــع الدعــاوى لــدى جميــع احملاكــم اإلداريــة‬\n‫(ديــوان املظالــم ) ولــدى هيئــة التحقيــق واالدعــاء العــام واســتخراج‬\n\n                                                                                         ‫‪266‬‬\n\f      ‫حجــة اســتحكام علــى امللــك الواقــع يف ‪.........‬بخميــس مشــيط واســتالم‬\n      ‫الصــك واالســتالم والتســليم ومراجعــة اجلهــات ذات العالقــة وإنهــاء‬\n      ‫جميــع اإلجــراءات الالزمــة والتوقيــع فيمــا يتطلــب ذلــك‪ ،‬وحضــر‬\n      ‫حلضوره‪.........‬ســعودي اجلنســية يحمــل الســجل املدنــي رقــم ‪.........‬بصفتــه‬\n      ‫وكيــا عــن املدعــى عليــه ‪.........‬ســعودي اجلنســية يحمــل الســجل املدنــي‬\n      ‫رقم‪.........‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجــازان‬\n      ‫برقــم ‪.........‬وتاريــخ ‪1429/11/12‬ه ـ املخــول لــه فيهــا حــق املطالبــة‬\n      ‫واملرافعــة واملدافعــة واملخاصمــة وإقامــة الدعــاوى ضــد الغيــر وإنهــاء مــا‬\n      ‫يلــزم احلضــور يف كل دعــوى تقــام منــه أو ضــده أمــام أي محكمــة ويف‬\n      ‫أي جهــة وإنهــاء كافــة اإلجــراءات املتعلقــة بذلــك ولــه احلــق يف ســماع‬\n      ‫الدعــوى والــرد عليهــا ومنــع التعــدي واإلقــرار واإلنــكار وطلــب وقبــول‬\n      ‫احلكــم ونفيــه واالعتــراض عليــه وطلــب متييــزه واإلحــداث علــى جميــع‬\n      ‫عقاراتــه مبنطقــة جــازان وعســير ومراجعــة اجلهــات احلكوميــة ذات‬\n      ‫العالقــة بــكل مــا يلــزم والتوقيــع عنــه وكالــة خاصــة فيمــا ذكــر‪،‬‬\n      ‫وادعــى األول قائــا يف دعــواه‪ :‬إنــه مــن اجلــاري يف ملــك موكلــي وحتــت‬\n      ‫تصرفــه كامــل األرض الواقعــة يف حــي ‪ .........‬مبحافظة خميس مشــيط‬\n      ‫والتــي حدودهــا وأطوالهــا كالتالــي‪ :‬يحدهــا شــما ًال مســيل ‪.........‬وطــول‬\n      ‫الضلــع مائــة واثنــان وعشــرون متــر ًا وســبعة وخمســون ســنتيمتر ًا وجنوبـ ًا‬\n      ‫شــارع عرضــه عشــرون متــر ًا يليــه مخطــط ‪.........‬وطــول الضلــع مائــة‬\n      ‫وســتة وعشــرون متـ ًـر ًا وثمانيــة وأربعــون ســنتيمتر ًا وشــرق ًا ملــك ‪.........‬‬\n      ‫وشــركاه وطــول الضلــع أربعــة وثمانــون متــر ًا وتســعة وتســعون ســنتيمتر ًا‬\n      ‫وغرب ـ ًا مســيلة وادي ويليهــا مزرعــة ‪.........‬وطــول الضلــع ثالثــة وثمانــون‬\n      ‫متــر ًا وثالثــة وتســعون ســنتيمتر ًا ومســاحتها اإلجماليــة ثمانيــة آالف‬\n\n\n‫‪267‬‬\n\f‫وأربعمائــة وواحــد وثالثــون متــر ًا مربع ـ ًا وقــد آلــت األرض املوصوفــة‬\n‫بعاليــه إلــى ملــك موكلــي بالشــراء مــن ‪ .........‬حامــل احلفيظــة رقــم ‪.........‬‬\n‫ســجل خميــس مشــيط مبوجــب عقــد مبايعــة مت يف ‪1421/9/15‬ه ـ‬\n‫كمــا آلــت إلــى البائــع ‪.........‬بــاإلرث مــن والــده الــذي أحياهــا قبــل‬\n‫عــام ‪1387‬ه ـ واألرض محــل الدعــوى هــي ملــك موكلــي وبيــده إال أن‬\n‫املدعــى عليــه قــد قــام ببيــع األرض ل‪.........‬قبــل أربــع ســنوات دون إذن‬\n‫موكلــي مبوجــب عقــد مبايعــة مت بينهمــا وبــن الفينــة واألخــرى يأتــي‬\n‫‪.........‬ملوكلــي ويدعــي بــأن األرض املوصوفــة أعــاه أرضــه قــد اشــتراها‬\n‫مــن املدعــى عليــه ‪.........‬فقــام موكلــي باالتصــال باملدعــى عليــه فذكــر‬\n‫ملوكلــي أنــه قــد بــاع األرض املوصوفــة بعاليــه مــن ‪ .........‬مببلــغ وقــدره‬\n‫أربعــون ألــف ريــال وأنــه قــد مت عقــد املبايعــة يف جــازان بــدون الوقــوف‬\n‫علــى األرض وال رؤيتهــا وقــال ملوكلــي‪ :‬إذا كانــت هنــاك مشــاكل‬\n‫علــى األرض فأبلــغ ‪.........‬بــأن يرجــع إلـ َّـي ألعطيــه املــال الــذي دفعــه وهــو‬\n‫أربعــون ألــف ريــال هكــذا ذكــر ملوكلــي وألن املدعــى عليــه قــد قــام‬\n‫ببيــع األرض املوصوفــة بعاليــه دون أن يكــون مالــكا لهــا ولــم يــأذن لــه‬\n‫موكلــي بذلــك ولكــون موكلــي قــد تضــرر مــن تعــرض ‪.........‬لــأرض‬\n‫فإنــه يطلــب احلكــم بإبطــال عقــد بيــع األرض املوصوفــة أعــاه الــذي مت‬\n‫بــن املدعــى عليــه أصالــة و‪.........‬هــذه دعــواي وبعــرض مــا جــاء يف دعــوى‬\n‫املدعــي وكالــة علــى املدعــى عليــه وكالــة أجــاب املدعــى عليــه وكالــة‬\n‫قائــا‪ :‬أطلــب إمهالــي للرجــوع إلــى موكلــي وأتعهــد بإحضــار اجلــواب‬\n‫محــرر ًا يف اجللســة القادمــة هكــذا أجــاب ولســماع إجابــة املدعــى‬\n‫عليــه علــى دعــوى املدعــي جــرى رفــع اجللســة وتأجيلهــا إلــى يــوم الســبت‬\n‫‪1434/7/29‬ه ـ الســاعة ‪ 10.00‬واختتمــت اجللســة الســاعة ‪10.00‬‬\n\n\n                                                                                          ‫‪268‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":265,"source_page_end":268,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"734dc003b0b24c93165ee1c3608be1e1bc8212392b2cab9a0076b2188d760e97","normalized_text_hash":"57995ae62b5ece286750dde4e232626193e7ead27853d9bd76812b4515a04e63","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p265-34284029"},{"id":"850931c3-d538-5fb7-9ba0-bc41a23f5e0d","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقار -شراء قطعة أرض باآلجل -قيام البائع ببيع العقار مرة ثانية لشخص آخر -طلب املشتري األول إبطال البيع الثاني وإدخال من انتقلت األرض إليه طرف ا يف الدعوى وإفراغ األرض له -الدفع بعدم الصفة -صرف النظر عن دعوى املدعي ألن دعوى استرداد احليازة يف العقار تقام على من بيده العن .","document_number":"34309361","case_number":"32535658","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/10","year":"1434","subject":"بيع -عقار -شراء قطعة أرض باآلجل -قيام البائع ببيع العقار مرة ثانية لشخص آخر -طلب املشتري األول إبطال البيع الثاني وإدخال من انتقلت األرض إليه طرف ا يف الدعوى وإفراغ األرض له -الدفع بعدم الصفة -صرف النظر عن دعوى املدعي ألن دعوى استرداد احليازة يف العقار تقام على من بيده العن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34309361:‬تاريخه ‪1434/298 :‬هـ‬\n                        ‫رقم الدعوى ‪32535658:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34356476‬تاريخه ‪1434/11/10:‬هـ‬\n\n\n      ‫بيــع ‪ -‬عقــار‪ -‬شــراء قطعــة أرض باآلجــل‪ -‬قيــام البائــع ببيــع العقــار‬\n      ‫مــرة ثانيــة لشــخص آخــر‪ -‬طلــب املشــتري األول إبطــال البيــع الثانــي‬\n      ‫وإدخــال مــن انتقلــت األرض إليــه طرف ـ ًا يف الدعــوى وإفــراغ األرض‬\n      ‫لــه‪ -‬الدفــع بعــدم الصفــة‪ -‬صــرف النظــر عــن دعــوى املدعــي ألن دعــوى‬\n                     ‫اســترداد احليــازة يف العقــار تقــام علــى مــن بيــده العــن ‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                               ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي وكالــة بــأن موكلــه اشــتري قطعــة أرض ( ذكــر‬\n      ‫وصفهــا) مــن بائعهــا ( ذكــر قيمتهــا ) تســدد خــال ثالثــة أشــهر‪ ،‬ســدد‬\n      ‫موكلــه قرابــة نصــف القيمــة‪ ،‬قــام البائــع ببيــع األرض للمدعــى عليــه‪،‬‬\n      ‫بعــد رفــع الدعــوى علــى املدعــى عليــه ظهــر أن ملكيتهــا انتقلــت الــى‬\n      ‫امــرأة (ذكراســمها) ‪ ،‬لكــون املدعــى عليــه اشــترى مــاال ميلكــه البائــع‬\n      ‫األول فقــد طلــب املدعــي وكالــة إبطــال هــذا البيــع وإدخــال املــرأة طرفـ ًا‬\n      ‫يف الدعــوى واحلكــم ملوكلــه بإفــراغ العقــار لــه وموكلــه علــى اســتعداد‬\n      ‫بإكمــال املتبقــي مــن املبلــغ‪ ،‬دفــع املدعــى عليــه بــأن موكلــه ليــس لــه‬\n\n‫‪273‬‬\n\f‫صفــه يف الدعــوى ولــم يقــم بإفــراغ العقــار باســمه مطلقاً‪،‬جــرى االطــاع‬\n‫علــى صــك األرض وذكــر وصفها‪،‬حيــث إن املتقــرر أن الدعــوى يف‬\n‫العقــار ترفــع علــى مــن بيــده العــن فقــد صــدر احلكــم بصــرف النظــر‬\n‫عــن دعــوى املدعــي ضــد املدعــى عليــه وإفهــام املدعــي وكالــة بــأن‬\n‫ملوكلــه إقامــة الدعــوى علــى مــن بيــده العــن‪ ،‬اعتــرض املدعــي وكالــة‬\n             ‫علــى احلكــم‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة بنــاء علــى االســتدعاء احملــال لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32535658‬وتاريــخ‬\n‫‪1432/11/18‬ه ـ املقيــد باحملكمــة برقــم ‪ 321465792‬وتاريــخ‬\n‫‪1432/11/18‬ه ـ ففــي يــوم االثنــن املوافق‪1433/02/01‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 : 30‬وفيهــا حضــر املدعــي وكالــة ‪ ،...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬الوكيــل الشــرعي عــن ‪...‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة‬\n‫جــدة برقــم ‪ 94624‬وتاريــخ ‪1432/11/05‬ه ـ واملخــول لــه فيهــا باملرافعــة‬\n‫واملدافعــة وقبــول األحــكام واالعتــراض عليهــا ولــم يحضــر املدعى عليه‬\n‫‪...‬وال مــن ميثلــه بوكالــة شــرعية ولــم يردنــا مــا يفيــد تبلغــه ‪ ،‬لــذا تقــرر‬\n‫رفــع اجللســة وتأجيلهــا إلــى يــوم الســبت األحــد املوافــق ‪1433/05/09‬ه ـ‬\n‫الســاعة التاســعة وبــاهلل التوفيــق ثــم بتاريــخ ‪1433/05/09‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر املدعــي وكالــة ‪...‬ولــم يحضــر املدعــى عليــه ‪...‬وال‬\n‫مــن ميثلــه بوكالــة شــرعية وقــد قــرر املدعــي وكالــة قائــا بأننــا لــم‬\n\n                                                                                        ‫‪274‬‬\n\f      ‫نتمكــن مــن إبــاغ املدعــى عليــه ونطلــب اإلمهــال لتبليــغ املدعــى عليــه‬\n      ‫فأجيــب لطلبــه وتقــرر رفــع اجللســة لذلــك ثــم بتاريــخ ‪1434/08/25‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعي وكالــه ‪ ...‬وحضر حلضوره املدعى‬\n      ‫عليــه وكالــه ‪...‬ســعودي اجلنســية ســجله املدنــي رقــم ‪...‬بصفتــه وكيــا‬\n      ‫شــرعيا عــن ‪ ...‬بالوكالــة الصــادرة مــن كتابــة عــدل الثانيــة بجنــوب‬\n      ‫جــدة برقــم ‪ 37724‬وتاريــخ ‪1431/11/26‬ه ـ والتــي تخــول لــه الســير يف‬\n      ‫القضيــة وبســؤال املدعــي وكالــه عــن دعــواه اجــاب قائــا ان موكلــي‬\n      ‫قــد اشــترى القطعــة رقــم ‪ ...‬الواقعــة يف مخطــط ‪ ...‬الواقــع جنوب مشــروع‬\n      ‫االميــر فــواز يف جــدة مــن ‪...‬بقيمــة اجماليــه قدرهــا ثالثمائــة وخمســة‬\n      ‫عشــر الــف ريــال وقــد كان االتفــاق علــى ان يقــوم موكلــي بســداد‬\n      ‫املبلــغ للبائــع ‪...‬خــال ثالثــة اشــهر وقــد قــام موكلــي بتســليم ‪...‬مبلغــا‬\n      ‫قــدره مائــة وخمســة وســتون الــف ريــال وقــد علــم موكلــي ان البائــع‬\n      ‫‪...‬قــد قــام ببيــع االرض لصالــح املدعــى عليــه ‪...‬وبعــد ان قــام موكلــي‬\n      ‫برفــع الدعــوى ضــد املدعــى عليــه ظهــر ان ملكيتهــا انتقلــت الــى‬\n      ‫‪...‬ولكــون املدعــى عليــه قــد اشــترى مــاال ميلكــه البائــع ‪...‬فانــي اطلــب‬\n      ‫ابطــال بيــع ‪......‬لقطعــة العقــار وادخــال ‪...‬طرفــا يف الدعــوى واحلكــم‬\n      ‫ملوكلــي بإفــراغ العقــار وموكلــي علــى اســتعداد بــان يكمــل املتبقــي‬\n      ‫مــن املبلــغ هــذه دعــواي وبعــد االطــاع علــى اوراق املعاملــة ظهــر صــورة‬\n      ‫الصــك الصــادر مــن كتابــة عــدل جــدة برقــم ‪ 420215010031‬وتاريــخ‬\n      ‫‪1434/02/11‬ه ـ واملتعلقــة بالقطعــة رقــم ‪ 359‬وقــد ظهــر ان حدودهــا‬\n      ‫واطوالهــا كمــا يلــي ( شــماال قطعــة رقــم ‪ 357‬بطــول ‪ 36‬ســتة وثالثــون‬\n      ‫متــر وجنوبــا قطعــة رقــم ‪ 361‬بطــول ‪ 36‬ســتة وثالثــون مترا وشــرقا شــارع‬\n      ‫عــرض ‪ 15‬م بطــول ‪ 25‬خمســة وعشــرون متــرا وغربــا قطعــة رقــم ‪358‬‬\n\n\n‫‪275‬‬\n\f‫بطــول خمســة وعشــرون متــرا) وبســؤال املدعــى عليــه وكالــه عمــا جــاء‬\n‫يف دعــوى املدعــي وكالــه فاجــاب قائــا ان موكلــي ليــس لــه صفــة يف‬\n‫هــذه الدعــوى ولــم يقــم بإفــراغ العقــار باســمه مطلقــا وال عالقــة ملوكلــي‬\n‫بهــذا العقــار مطلقــا هكــذا اجــاب وبعــرض ذلــك علــى املدعــي وكالــه‬\n‫قــال ان موكلــي مصــر علــى ان املدعــى عليــه قــد اشــترى هــذا العقــار‬\n‫وافــرغ باســمه عليــه وبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة وحيــث‬\n‫ان املدعــي قــد قــرر يف دعــواه علــى ان العقــار بيــد غيــر يــد املدعــى عليــه‬\n‫وحيــث إنــه ظهــر مــن صــورة الصــك املرفــق ان العقــار بيــد ‪...‬وحيــث إنــه‬\n‫مــن املتقــرر ان الدعــوى يف عقــار ترفــع علــى مــن بيــده العــن جلميــع مــا‬\n‫تقــدم فقــد حكمــت بصــرف النظــر عــن دعــوى املدعــي ‪...‬ضــد املدعــى‬\n‫عليــه ‪...‬وافهمــت املدعــي وكالــه بــان ملوكلــه اقامــة الدعــوى علــى مــن‬\n‫بيــده العــن ان اراد ذلــك وبعــرض احلكــم علــى الطرفــن قــرر املدعــي‬\n‫وكالــه عــدم القناعــة وقــرر املدعــى عليــه وكالــه القناعــة وافهمــت‬\n‫املدعــى وكالــه باملراجعــة يــوم الثالثــاء املوافــق ‪1434/09/01‬ه ـ‬\n‫الســتالم صــورة مــن صــك احلكــم لتقــدمي الئحتــه االعتراضيــة عليــه‬\n‫خــال املــدة النظاميــة ففهــم ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/08/25‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 321465792‬وتاريــخ‬\n‫‪1434/11/19‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪ 3214465792‬وتاريخ‬\n‫‪1434/11/26‬ه ـ واملصدقــة مــن الدائــرة احلقوقيــة الرابعــة مبحكمــة‬\n‫االســتئناف مبكــة املكرمــة بالقــرار الصــادر مــن أصحــاب الفضيلــة‬\n‫قضــاة محكمــة االســتئناف رقــم ‪ 34356476‬وتاريــخ ‪1434/11/10‬ه ـ‬\n\n\n                                                                                       ‫‪276‬‬\n\f      ‫املتضمــن مــا نصــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة‬\n      ‫علــى احلكــم وعلــى فضيلتــه مراعــاة التنبيــه املرفــق باملعاملــة وبــاهلل‬\n      ‫التوفيــق أهــ‪ .‬قاضــي اســتئناف ختــم وتوقيــع ‪...‬وقاضــي اســتئناف ختــم‬\n      ‫وتوقيــع ‪ ...‬ورئيــس الدائــرة موقــع يف األصــل وموافــق علــى احلكــم‬\n      ‫ومجــاز ‪ ، ...‬عليــه فقــد أمــرت بإحلــاق ذلــك بالضبــط وســجله وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                              ‫يف ‪1434/12/01‬ه ـ ‪.‬‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد‪ :‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن‬\n      ‫فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد‬\n      ‫‪34309361‬وتاريــخ ‪1434/8/29‬هـ ـ املتضمــن دعــوى (وكالــة) ‪ ...‬ضــد‬\n      ‫‪(...‬وكالــة) واحملكــوم فيــه مبــا دون باطنــة وبدراســة الصــك وصــورة‬\n      ‫ضبطــه تقــررت املوافقــة علــى احلكــم وعلــى فضيلتــه مراعــاة التنبيــه‬\n      ‫املرفــق باملعاملــة ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                             ‫وســلم‪.‬‬\n\n\n\n\n‫‪277‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":273,"source_page_end":277,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"63f7f5b281f826fa9f667a4084276531ec7aa7347ccfbb439a44fa075d301bc8","normalized_text_hash":"2de8633d1d05a18bf92726845f748d5dd68a6e3235febb197c8697bcd02e5c88","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p273-34309361"},{"id":"3b46b5be-6692-51fa-806c-c416a0e392eb","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع بالتقسيط -بطاقات سوا -حترير شيكات بكامل املبلغ -الزيادة يف السعر من أجل األجل -اشتراط حلول جميع األقساط املتبقية عند التأخر يف سداد قسطني -املسلمون على شروطهم -صرف النظر عن دعوى املدعي إلتزام ا بالعقد .","document_number":"34328427","case_number":"348605","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/12","year":"1434","subject":"بيع بالتقسيط -بطاقات سوا -حترير شيكات بكامل املبلغ -الزيادة يف السعر من أجل األجل -اشتراط حلول جميع األقساط املتبقية عند التأخر يف سداد قسطني -املسلمون على شروطهم -صرف النظر عن دعوى املدعي إلتزام ا بالعقد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/10/12 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34328427 :‬‬\n                       ‫َر ْق ُم الدعوى‪348605 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34361552‬تاريخه‪1434/11/18 :‬هـ‬\n\n\n  ‫بيع بالتقســيط ‪ -‬بطاقات ســوا ‪ -‬حترير شــيكات بكامل املبلغ ‪ -‬الزيادة‬\n  ‫يف الســعر مــن أجــل األجــل ‪ -‬اشــتراط حلــول جميــع األقســاط املتبقيــة‬\n  ‫عنــد التأخــر يف ســداد قســطني ‪ -‬املســلمون علــى شــروطهم ‪ -‬صــرف‬\n                               ‫النظــر عــن دعــوى املدعــي إلتزامـ ًا بالعقــد ‪.‬‬\n\n\n\n\n  ‫قــول النبــي صلــى اهلل عليــه وســلم ‪ (:‬املســلمون علــى شــروطهم إال‬\n                               ‫شــرط ًا حــرم حــا ًال أو أحــل حرام ـ ًا ) ‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي بأنــه اشــترى مــن املدعــى عليــه بطاقــات ســوا مببلــغ‬\n  ‫خمســة عشــر ألــف ريــال مقســطه علــى عشــرة أشــهر ميالديــة ‪ ،‬وقــد‬\n  ‫حــرر لــه شــيكات بكامــل املبلــغ ‪ ،‬بعــد ســداد قســطني قــدم املدعــى‬\n  ‫عليــه (الدائــن) شــكوى علــى املدعــي يف هــذه القضيــة (املديــن) لــدى‬\n  ‫الشــرطة إللزامــه بســداد قيمــة الشــيكات احملــررة بكامــل املبلــغ مــع‬\n  ‫أنهــا لــم حتــل ‪ ،‬ســدد املدعــى قيمــة هــذه الشــيكات ‪ ،‬لكــون املدعــى‬\n  ‫عليــه زاد يف ســعر البطاقــات مــن أجــل األجــل ثــم أخــذ املبلــغ حــا ًال فقــد‬\n  ‫طلــب املدعــي إلــزام املدعــى عليــه بإعــادة مــا زاد مــن القيمــة مــن أجــل‬\n  ‫األجــل مبلغـ ًا قــدره خمســة آالف ريــال ‪ ،‬صــادق املدعــى عليــه على دعوى‬\n\n                                                                                         ‫‪278‬‬\n\f      ‫املدعــي ودفــع بــأن مــن شــروط العقــد أنــه إذا تأخــر املديــن عــن ســداد‬\n      ‫قســطني فــإن املبلــغ يحــل بالكامــل ‪ ،‬وقــد تأخــر املشــتري (املدعــي) عــن‬\n      ‫ســداد قســطني ‪ ،‬صــادق املدعــي علــى مــا ذكــره املدعــى عليــه ‪ ،‬جــرى‬\n      ‫االطــاع علــى العقــد و ال ــتأكد مــن صحــة الشــرط املذكــور ‪ ،‬بنــاء‬\n      ‫علــى قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬املســلمون علــى شــروطهم) لــذا‬\n      ‫جــرى صــرف النظــر عــن دعــوى املدعــي ‪ ،‬اعتــرض املدعــي علــى احلكــم‬\n                                    ‫‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة بعنيــزة‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بعنيــزة برقــم ‪ 348605‬وتاريــخ ‪ 1434/01/06‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 3439791‬وتاريــخ ‪ 1434/01/06‬ه ـ فقــد حضــر املدعــي ‪...‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وحضــر املدعــى عليــه ‪...‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وقــد طلبــت مــن املدعــي‬\n      ‫حتريــر دعــواه فادعــى قائــا إننــي قــد قمــت بشــراء عــدد ألــف بطاقــة‬\n      ‫ســوا مــن املدعــى عليــه بقيمــة خمســة عشــر ألــف ريــال مقســطة علــى‬\n      ‫عشــرة أشــهر ميالديــة كل شــهر قســط وقــدره ألــف وخمســمائة ريــال‬\n      ‫ابتــداء مــن ‪2012/9/3‬م وقــد حــررت لــه شــيكات بكامــل املبلغ وقدره‬\n      ‫خمســة عشــر ألــف ريــال وبعــد ســدادي لقســطني بقيمــة ثالثــة آالف ريــال‬\n      ‫قــدم املدعــى عليــه شــكوى علــي لــدى الشــرطة إللزامــي بســداد قيمــة‬\n      ‫الشــيكات احملــررة بكامــل املبلــغ مــع أنهــا لــم حتــل فتــم اســتدعائي‬\n      ‫مــن قبــل الشــرطة وإلزامــي بســداد كامــل الشــيكات املتبقيــة وقيمتهــا‬\n‫‪279‬‬\n\f‫اثنــا عشــر ألــف ريــال فقمــت بتســديدها كاملــة ولكــون املدعــى عليــه‬\n‫زاد خمســة آالف ريــال يف ســعر البطاقــات مــن أجــل األجــل ثــم أخــذ املبلغ‬\n‫حــاال فإنــي أطلــب الــزام املدعــى عليــه بإعــادة مــا زاده مــن أجــل األجــل‬\n‫وقــدره خمســة آالف ريــال هكــذا ادعــى املدعــي وبســؤال املدعــى عليــه‬\n‫عــن دعــوى املدعــي أجــاب بقولــه مــا ذكــره املدعــي يف دعــواه صحيــح‬\n‫جملــة ولكننــي اتفقــت أنــا واملدعــي يف العقــد املبــرم بيننــا علــى أنــه إذا‬\n‫تأخــر يف ســداد قســطني فــإن مبلــغ البيــع يحــل كامــا ويكــون واجــب‬\n‫الدفــع وقــد تأخــر املدعــي يف قســطني فقمــت بتنفيــذ العقــد املبــرم بيننــا‬\n‫وتصرفــت مبوجبــه وشــكوته علــى الشــرطة فســدد املبلــغ الباقــي الــذي‬\n‫يف الشــيكات كامــا هكــذا أجــاب وقــد أبــرز املدعــى عليــه العقــد‬\n‫املوقــع بــن الطرفــن وقــد جــاء يف البنــد الرابــع منــه يلتــزم الطــرف‬\n‫الثانــي بدفــع األقســاط يف موعدهــا وأن أي قســط يتأخــر فهــو واجــب‬\n‫الدفــع مــع القســط الــذي حــل أجلــه ويدفعــان معــا اســتيفاء بأثــر رجعــي‬\n‫ويف حــال تأخــر قســطني فــإن مبلــغ عقــد البيــع يحــل كامــا ويكــون‬\n‫واجــب الدفــع ثــم ســألت املدعــي عــن جــواب املدعــى عليــه فقــرر بقولــه‬\n‫مــا ذكــره املدعــي يف جوابــه صحيــح هكــذا قــرر ثــم ســألته عــن العقــد‬\n‫فقــال العقــد صحيــح وقــد وقعــت عليــه مبحــض إرادتــي ولــم يتــم إجبــاري‬\n‫أو التغريــر بــي وكنــت عاملــا بالبنــد الرابــع وموافقــا عليــه هكــذا قــرر‬\n‫ويف جلســة أخــرى لــدي أنــا املــازم القضائــي ‪...‬القائــم بعمــل فضيلــة‬\n‫الشــيخ ‪...‬القاضــي يف احملكمــة العامــة بعنيــزة أثنــاء إجازتــه حضــر‬\n‫املدعــي أصالــة ولــم يحضــر املدعــى عليــه وال مــن ميثلــه وبعــد التأمــل‬\n‫واالطــاع علــى ملــف القضيــة وبنــاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n‫وجــواب املدعــى عليــه وبنــاء علــى قــول النبــي صلــى اهلل عليــه وســلم‬\n\n\n                                                                                      ‫‪280‬‬\n\f      ‫(املســلمون علــى شــروطهم ‪ ،‬إال شــرطا حــرم حــاال ‪ ،‬أو أحــل حرامــا)‬\n      ‫وبنــاء علــى أن العقــد قــد وقــع عليــه مــن قبــل املدعــي مبحــض إرادتــه‬\n      ‫وبعــد إطالعــه علــى جميــع مــا فيــه مــن بنــود ومــن ضمنهــا البنــد الرابــع‬\n      ‫يلتــزم الطــرف الثانــي بدفــع األقســاط يف موعدهــا وأن أي قســط يتأخــر‬\n      ‫فهــو واجــب الدفــع مــع القســط الــذي حــل أجلــه ويدفعــان معــا اســتيفاء‬\n      ‫بأثــر رجعــي ويف حــال تأخــر قســطني فــإن مبلــغ عقــد البيــع يحــل كامــا‬\n      ‫ويكــون واجــب الدفــع وملصادقــة املدعــي علــى جــواب املدعــى عليــه مــن‬\n      ‫أنــه قــد تأخــر بســداد قســطني متتالــن فقــد صرفــت النظــر عــن دعــوى‬\n      ‫املدعــي ضــد املدعــى عليــه وبــه حكمــت وبعــرض احلكــم علــى املدعــي‬\n      ‫قــرر عــدم القناعــة وطلــب االســتئناف بــدون الئحــة اعتراضيــة فأجبتــه‬\n      ‫لطلبــه وأمــرت برفــع املعاملــة حملكمــة االســتئناف حســب التعليمــات‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                           ‫حــرر يف ‪ 1434/10/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬املــازم القضائــي القائــم بعمل فضيلة‬\n      ‫الشــيخ ‪ ...‬القاضــي يف احملكمــة العامــة بعنيــزة وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بعنيــزة برقــم ‪348605‬‬\n      ‫وتاريــخ ‪ 1434/01/06‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3439791‬وتاريــخ‬\n      ‫‪ 1434/01/06‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/12/03‬هـ افتتحت‬\n      ‫اجللســة وقــد عــادت إلينــا املعاملــة مــن محكمــة االســتئناف برقــم‬\n      ‫‪ 342458487‬يف ‪1434/12/2‬ه ـ وبرفقهــا القــرار رقــم ‪34361552‬‬\n      ‫يف ‪1434/11/18‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة» وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة‬\n      ‫علــى احلكــم» وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n‫‪281‬‬\n\f                                ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/12/03‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n‫وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة عنيــزة بـرق ــم ‪ 3439791‬وتاريــخ ‪10 /26‬‬\n‫‪1434/‬هــ؛ احملالـة إلـيـنـا برقم ‪ 34484840‬؛ املرفق بها الصك املسجل‬\n‫ب ــرقم ‪ 34328427‬وتاريــخ ‪1434 / 10 /12‬هـ ـ الصــادر مــن فضيلــة‬\n‫الشــيخ‪ ... /‬املــازم القضائــي باحملكمــة؛ اخلــاص بدع ــوى‪... /‬ضــد‪،... /‬‬\n‫بش ــأن شــراء عــدد مــن بطاقــات ســواء بقيمــة خمســة عشــر ألــف ريــال‬\n‫مقســطة علــى عشــرة أشــهر ميالديــة؛ وطلــب إلــزام املدعــى عليــه بإعــادة‬\n‫مــا زاد مــن أجــل اآلجــل وقــدره خمســة آالف ريــال‪ ،‬وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه بصــرف النظــر عــن دعــوى املدعــي؛ علــى النحــو املفصــل‬\n‫فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى‬\n                                     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪282‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":278,"source_page_end":282,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"491fc99d02078b4d4c43f86cc6380c564f3fbae24e2f556f20dbb36b107dcf8f","normalized_text_hash":"599ebe282ac65ac1c77a1ac8ac8c20d01bf5acad0289c318b8811a29f5c7aaad","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p278-34328427"},{"id":"6ab30eca-a2ed-52fd-92b8-62cf94f9d9a9","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -بيع -إعادة ثمن املبيع لعدم التسليم واإلفراغ -اإلقرار حجة على املقر -احلكم برد ثمن املبيع حضوري ا.","document_number":"34220791","case_number":"46220130","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/25","year":"1434","subject":"عقد -بيع -إعادة ثمن املبيع لعدم التسليم واإلفراغ -اإلقرار حجة على املقر -احلكم برد ثمن املبيع حضوري ا.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/25 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34220791 :‬‬\n                         ‫َر ْق ُم الدعوى‪46220130 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34277771‬تاريخه‪1434/7/24 :‬هـ‬\n\n\n      ‫عقــد ‪ -‬بيــع ‪ -‬إعــادة ثمــن املبيــع لعــدم التســليم واإلفــراغ ‪ -‬اإلقــرار‬\n                        ‫حجــة علــى املقــر ‪ -‬احلكــم بــرد ثمــن املبيــع حضوري ـ ًا‪.‬‬\n\n\n\n                                                ‫‪ -1‬اإلقرار حجة على املقر ‪.‬‬\n                ‫‪ -2‬املرء مؤاخذ بإقراره إذا صدر منه على الصفة املشروعة ‪.‬‬\n      ‫‪ -3‬املــواد (‪ )1/55‬و(‪ )4/176‬و(‪ )178‬مــن نظــام املرافعــات الشــرعية‬\n                                                      ‫والئحتــه التنفيذيــة‪.‬‬\n\n\n\n      ‫ادعــت املدعيــة بأنهــا اتفقــت مــع املدعــى عليــه علــى شــراء شــقة متليــك‬\n      ‫ودفعــت لــه كامــل املبلــغ املتفــق عليــه إال أن املدعــى عليــه لــم يســلمها‬\n      ‫الشــقة املذكــورة وقــام ببيعهــا علــى شــخص آخــر‪ ،‬ولــذا طلبــت احلكــم‬\n      ‫عليــه بإعــادة كامــل املبلــغ الــذي اســتلمه منهــا‪ ،‬أنكــر وكيــل املدعــى‬\n      ‫عليــه مــا جــاء يف الدعــوى ودفــع بــأن املدعيــة طلبــت مــن موكلــه شــراء‬\n      ‫شــقتني وســلمته قيمــة إحداهمــا ولــم تســلمه قيمــة األخــرى فســلمها‬\n      ‫شــقة واحــدة فقــط‪ ،‬طلبــت احملكمــة مــن املدعيــة بينتهــا علــى دعواهــا‬\n      ‫فقدمــت ثــاث ســندات قبــض تتضمــن تســليم املدعيــة مبالــغ نقديــة‬\n      ‫مقابــل شــراء شــقة متليــك تعــادل يف مجموعهــا إجمالــي قيمتهــا‪ ،‬كمــا‬\n      ‫قدمــت مــا يثبــت أن الشــقة التــي يدعــي املدعــى عليــه تســليمها لهــا مت‬\n‫‪283‬‬\n\f‫ســداد قيمتهــا لــه عــن طريــق متويــل عقــاري لصالــح زوج ابنتهــا‪ ،‬املدعــى‬\n‫عليــه أقــر أمــام جهــة التحقيــق بأنــه اســتلم مــن املدعيــة مبلــغ يعــادل قيمــة‬\n‫شــقة التمليــك محــل الدعــوى واملــرء مؤاخــذ بإقــراره إذا صــدر منــه علــى‬\n‫الصفــة املشــروعة‪ ،‬قضــت احملكمــة حضوريـ ًا بإلــزام املدعــى عليــه أن‬\n‫يدفــع للمدعيــة املبلــغ املدعــى بــه حــا ًال ‪ ،‬قــررت محكمــة االســتئناف‬\n                                                          ‫املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم ‪ 46220130‬وتاريــخ‬\n‫‪1432/02/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3215547‬وتاريــخ‬\n‫‪1432/02/21‬ه ـ ففــي يــوم االربعــاء املوافــق ‪1432/05/09‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــرت (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )........‬وادعــت علــى الغائــب عــن املجلــس الشــرعي قائلــه يف‬\n‫دعواهــا عليــه لقــد اتفقــت مــع املدعــى عليــه علــى شــراء شــقة متليــك‬\n‫مببلــغ ‪ 500.000‬ريــال خمســمائة الــف ريــال وقــد دفعــت املبلــغ كامــا‬\n‫إال أن املذكــور مياطــل ولــم يعطينــي الشــقة ومت بيعهــا علــى شــخص آخــر‬\n‫اطلــب احلكــم علــى املدعــى عليــه بإعــادة كامــل املبلغ وقدره خمســمائة‬\n‫الــف ريــال هــذه دعــواي هــذا وحلضــور املدعــى عليــه تأجلــت اجللســة ثــم يف‬\n‫جلســة أخــرى حضــر (‪ )........‬بالســجل املدنــي رقــم (‪ )........‬الوكيــل‬\n‫الشــرعي ‪ 65068‬وتاريــخ ‪1432/7/13‬ه ـ جلــد ‪ 10842‬عــن والتــي‬\n‫تخولــه املرافعــة واملدافعــة ولــم يحضــر املدعــى عليــه وال وكيــل عنــه‬\n\n                                                                                          ‫‪284‬‬\n\f      ‫وإلحضــار املدعــى عليــه تأجلــت اجللســة ثــم يف جلســة أخــرى حضــر‬\n      ‫بالســجل املدنــي رقــم الوكيــل الشــرعي ‪ 65068‬وتاريــخ ‪1432/7/13‬هـ‬\n      ‫جلــد ‪ 10842‬عــن والتــي تخولــه املرافعــة واملدافعــة وحضــر (‪)........‬‬\n      ‫بالســجل املدنــي رقــم (‪ )........‬الوكيــل الشــرعي بالوكالــة رقــم ‪27469‬‬\n      ‫وتاريــخ ‪1430/08/17‬ه ـ كتابــة عــدل جــدة عــن وبعــرض الدعــوى علــى‬\n      ‫املدعــى عليــه أجــاب اطلــب امهالــي للــرد علــى الدعــوى وعليــه تأجلــت‬\n      ‫اجللســة ثــم يف جلســة أخــرى حضــر وكيــل املدعيــة ولــم يحضــر املدعــى‬\n      ‫عليــه وبســؤال املدعــي وكالــة عــن ســندات دفــع قيمــه الشــقة واحضــار‬\n      ‫املدعــى عليــه تأجلــت اجللســة ثــم يف جلســة أخــرى لــدي أنــا (‪)00........00‬‬\n      ‫القاضــي يف احملكمــة العامــة مبحافظــة جــدة خلــف فضيلــة الشــيخ‬\n      ‫(‪ )........‬عليــه ففــي يــوم األحــد املوافــق ‪1433/10/22‬ه ـ افتتحت اجللســة‬\n      ‫الســاعة ‪ 10 : 00‬وفيهــا حضــر (‪ )........‬املدونــة هويتــه ووكالتــه ســابقا‬\n      ‫ولــم يحضــر املدعــى عليــه بالرغــم مــن تبلغــه عــن طريــق وكيلــه يف يــوم‬\n      ‫األحــد املوافــق ‪1433/6/22‬ه ـ وبتــاوة مــا مت ضبطــه ســابق ًا صــادق‬\n      ‫عليــه وبســؤاله عــن موقــع الشــقة التــي مت االتفــاق علــى بيعهــا أجــاب‬\n      ‫قائــا هــي شــقة يف عمــارة بحــي (‪ )........‬وبســؤاله عــن البينــة التــي وعــد‬\n      ‫بإحضارهــا أبــرز ســند قبــض مــن الصفقــة االولــى لالســتثمار والتطويــر‬\n      ‫العقــاري واملتضمــن مــا نصــه اســتلمنا مــن الســيدة (‪ )........‬مبلــغ وقــدره‬\n      ‫عشــرة أالف ريــال ال غيــر نقــد ًا بتاريــخ ‪1431-3-11‬ه ـ بالرقــم ســند‬\n      ‫‪ 5134‬وذلــك عــن مقابــل تكملــة عربــون شــقتني مقابــل بعــض يف دور‬\n      ‫واحــد الــدور الثانــي أو الرابــع يف عمــارة وســند قبــض مــن الصفقــة‬\n      ‫االولــى لالســتثمار والتطويــر العقــاري ونصــه اســتلمنا مــن الســيدة‬\n      ‫(‪ )........‬مبلــغ وقــدره أربعمائــة وخمســون الــف ريــال ال غيــر بتاريــخ‬\n\n\n‫‪285‬‬\n\f‫‪1431/3/13‬ه ـ بالرقــم ســند ‪ 5141‬عــن طريــق حوالــة نقديــة مســحوبة‬\n‫علــى بنــك (‪ )........‬عــن طريــق شــيك مصــدق برقــم ‪ 533822‬يف‬\n‫‪1431/3/13‬ه ـ وذلــك مقابــل شــراء شــقة متليــك بحــي النســيم اجلديــد‬\n‫والباقــي ‪ 40000‬الــف ريــال ويتــم دفــع باقــي املبلــغ بعــد شــهرين وســند‬\n‫قبــض مــن (‪ )........‬ونصــه اســتلمنا مــن الســيدة(‪ )........‬مبلــغ وقــدره‬\n‫أربعــون الــف ريــال ألغيــر نقــدا بتاريــخ ‪1431/4/18‬ه ـ بالرقــم ســند‬\n‫‪ 5264‬وذلــك عــن (‪ )........‬تكملــة مــا تبقــى مــن إجمالــي املبلــغ لشــقة‬\n‫متليــك يف حــي (‪ )........‬يف عمــارة وعليــه جــرى تأجيــل اجللســة لتبليــغ‬\n‫املدعــى عليــه مــرة أخــرى ثــم يف جلســة أخــرى حضــرت املدعيــة أصالــة‬\n‫(‪ )........‬ســعودية بالســجل رقــم (‪ )........‬بهــا مــن قبــل زوج ابنتهــا (‪)........‬‬\n‫ســعودي بالســجل رقــم (‪ )........‬ولــم يحضــر املدعــى عليــه وحيــث وردنــا‬\n‫خطــاب قســم محضــري اخلصــوم باحملكمــة برقــم ‪33/ 186410017‬‬\n‫واملتضمــن أنــه مت التوجــه إلــى املوقــع وتبــن أن املؤسســة انتقلــت إلــى‬\n‫مــكان آخــر وبنــاء علــى ذلــك تعــذر التبليــغ لهــذا اليــوم الســبت املوافــق‬\n‫‪1434/1/3‬ه ـ ولتبليــغ املدعــى عليــه عــن طريــق البحــث والتحــري جــرى‬\n‫تأجيــل اجللســة ثــم يف جلســة أخــرى حضــر املدعــي وكالــة واملدونــة‬\n‫هويتــه ووكالتــه ســابق ًا ولــم يحضــر املدعــى عليــه ولــم يردنــا مــا يفيــد‬\n‫تبلغــه ولتبليــغ املدعــى عليــه جــرى تأجيــل اجللســة ثــم يف جلســة أخــرى‬\n‫حضــر املدعــي وكالــة املدونــة هويتــه ووكالتــه ســابق ًا وحضــر حلضــوره‬\n‫املدعــى عليــه وكالــة (‪ )........‬ســعودي بالســجل رقــم (‪ )........‬بصفتــه‬\n‫ا عــن بالوكالــة الصــادرة مــن كتابــة عــدل شــمال جــدة الثانيــة‬       ‫وكي ـ ً‬\n‫برقــم ‪ 33377433‬يف ‪1433/11/14‬ه ـ وبســؤال املدعــى عليــه وكالــة‬\n‫عــن دعــوى املدعــي أجــاب قائــا أطلــب املهلــة للــرد يف اجللســة القادمــة‬\n\n\n                                                                                         ‫‪286‬‬\n\f      ‫كمــا جــرى تســليمه نســخة مــن املســتندات للجــواب عليهــا وعليــه جــرى‬\n      ‫تأجيــل اجللســة ثــم يف جلســة أخــرى حضــر املدعــي وكالــة املدونــة هويتــه‬\n      ‫ووكالتــه ســابق ًا وحضــر حلضــوره املدعــى عليــه وكالــة املدونــة هويتــه‬\n      ‫ووكالتــه ســابق ًا وبســؤال املدعــى عليــه وكالــة عمــا اســتمهل مــن أجلــه‬\n      ‫قــدم مذكــرة جوابيــة ونصهــا مــا يلــي ‪ :‬أوالً‪ :‬تقدمــت املدعيــة ملؤسســة‬\n      ‫موكلــي بطلــب شــراء شــقتني متليــك لهــا وألحــد أقاربهــا ‪ ،‬قيمــة كل‬\n      ‫شــقة خمســمائة ألــف ريــال‪ ،‬وقــد قامــت بدفــع قيمــة شــقة واحــدة فقــط‬\n      ‫أمــا الشــقة الثانيــة فإنهــا لــم تقــم بدفــع قيمتهــا‪ ،‬وهو ما أثبتته مســتندات‬\n      ‫املدعيــة نفســها‪ ،‬وعليــه فــإن املدعيــة لــم تقــل احلقيقــة كاملــة فقــد‬\n      ‫اشــترت شــقتني مــن مؤسســة موكلــي‪ ،‬ودفعــت قيمــة شــقة واحــدة‬\n      ‫فقــط‪ .‬ثاني ـاً‪ :‬املدعيــة اســتلمت الشــقة ومفاتيحهــا‪ ،‬وســكنت هــي أو‬\n      ‫قريبهــا املشــارك يف الشــراء يف الشــقتني‪ ،‬وهــي الواقعــة بحــي (‪)........‬‬\n      ‫بالــدور الثانــي مقابــل جامــع (‪ .)........‬ثالثـاً‪ :‬لقــد قامــت املدعيــة يف أصــل‬\n      ‫هــذه الدعــوى برفــع الدعــوى يف قســم شــرطة اجلامعــة علــى كل املدعــى‬\n      ‫عليــه هنــا ‪ ،‬؛ وهــو الــذي بيــده العقــار يف ذلــك الوقــت ‪ ،‬إال أن لــم ُيطلــب‬\n      ‫يف هــذه القضيــة هنــا يف احملكمــة ‪ ،‬فلعــل اســقاطه مــن املطالبــة لصلــة‬\n      ‫القرابــة بينهمــا أو ألمــر يضمرانــه بينهمــا ‪ ،‬وقــد ســمعت املدعيــة إقــراره‬\n      ‫بحــق موكلــي يف الشــقة التــي اشــترتها الســيدة الكرميــة لــدى قســم‬\n      ‫شــرطة اجلامعــة ‪ ،‬كمــا أن هنالــك قضيــة مرفوعــة مــن موكلــي ضــد‬\n      ‫(‪ )........‬لــدى فضيلــة القاضــي (‪ )........‬ومرفــق لفضيلتكــم صــورة مــن‬\n      ‫الالئحــة التــي أجــاب بهــا لــدى فضيلــة القاضــي (‪ )........‬والتــي يقــر فيهــا‬\n      ‫بحــق موكلــي يف الشــقق محــل الدعــوى‪ ،‬وعليــه فــإن ذلــك يــدل مبــا ال‬\n      ‫يــدع ألحــدٍ مجــا ًال الشــك يف أن موكلــي قــد أوفــى بالتزامــه نحــو‬\n\n\n‫‪287‬‬\n\f‫الســيدة‪ ،‬وإن كان لهــا مــن مطالبــة فهــي ضــد (‪ )........‬وليــس ضــد‬\n‫موكلــي‪ ،‬إلقــراره بحــق موكلــي‪ ،‬وإخاللــه مبــا التــزم بــه نحــو موكلــي‬\n‫وحقوقــه‪ ،‬فقــد التــزم بــأن يفــرغ الشــقق املذكــورة لــكل مــن يرســله‬\n‫موكلــي إليــه‪ .‬رابع ـاً‪ :‬الســتجالء األمــر فإنــا نطلــب مــن فضيلتكــم‬\n‫إحضــار (‪ )........‬وســؤاله عــن الشــقة ‪ ،‬ومــا هــو موقــف موكلــي مــن ذلــك‬\n‫مــع العلــم أن املدعيــة قــد أثبتــت لفضيلتكــم أن الشــقة يف عمــارة‬\n‫باســم(‪ .)........‬خامسـاً‪ :‬إذا ثبــت لفضيلتكــم وهــو مــا أثبتنــاه لكــم ومــا‬\n‫هــو ثابــت باملضبوطــات لــدى فضيلــة الشــيخ (‪ )........‬وثابــت بشــهادة‬\n‫الشــهود وبإقــرار يف حــق موكلــي يف الشــقة املباعــة فإنــه إن كان قــد‬\n‫اتفــق فيــه مــع املدعيــة علــى أمــر بينهمــا وأخــا بــه فيمــا بينهمــا ونحــن ال‬\n‫نعلــم عنــه فــإن العقــار موجــود‪ ،‬وإذا ثبــت حــق املدعيــة فــإن القاعــدة‬\n‫الشــرعية أن الدعــوى علــى مــن بيده العقار‪ .‬وعليـ ــه نأمــل من فضيلتكم‬\n‫احلكــم مبــا يلــي ‪ :‬أو ًال ‪ :‬أطلــب حضــور (‪ )........‬وســؤاله عــن كل‬\n‫مجريــات القضيــة‪ .‬ثاني ـاً‪ :‬صــرف النظــر عــن الدعــوى‪ ،‬حيــث أنــه قــد‬\n‫أدى مــا عليــه واســتلمت املدعيــة الشــقة‪ ،‬بــل قــد تبقــى علــى املدعيــة دفــع‬\n‫قيمــة الشــقة التــي اشــترتها مــن موكلــي ‪ ،‬لــم يســتلمها موكلــي إلــى‬\n‫حينــه وبعرضــه علــى املدعــي وكالــة قــال أطلــب املهلــة للــرد يف اجللســة‬\n‫القادمــة وعليــه جــرى تأجيــل اجللســة ثــم يف جلســة أخــرى حضــرت‬\n‫املدعيــة أصالــة (‪ )........‬ســعودية بالســجل رقــم (‪ )........‬ولــم يحضــر‬\n‫املدعــى عليــه يحــي بالرغــم مــن تبلــغ وكيلــه باملوعــد يف اجللســة املاضيــة‬\n‫وبســؤال املدعيــة عمــا اســتمهل وكيلهــا مــن أجلــه قدمــت مذكــرة‬\n‫جوابيــة هــذا نصهــا ‪ :‬أو ًال هــذا الــكالم غيــر صحيــح حســب العقــد‬\n‫واإليصــاالت الدفــع امــا بالنســبة للشــقة االولــى وحتمــل الرقــم (‪ )4‬وهــي‬\n\n\n                                                                                         ‫‪288‬‬\n\f      ‫باســم الســيد(‪ )........‬وقــد مت شــرائها عــن طريــق التمويــل العقــاري مــن‬\n      ‫بنــك (‪ )........‬وذللــك حســب العقــد املرفــق أمــا بالنســبة للشــقة الثانيــة‬\n      ‫وحتمــل الرقــم (‪ )3‬وهــي باســم (‪ )........‬وقــد مت دفــع املبلــغ بالكامــل‬\n      ‫للمدعــى عليــه حســب االيصــاالت املرفقــة‪ .‬ثاني ـاً‪ :‬هــذا الــكالم غيــر‬\n      ‫صحيــح لــم يتــم اســتالم الشــقة اخلاصــة باســم شــقة رقــم (‪ )3‬بــل مت بيعهــا‬\n      ‫لشــخص اخــر وأظــن ان وكيــل املدعــي عليــه ال يعلــم أن الســيد (‪)........‬‬\n      ‫اقــر واعتــرف يف شــرطة اجلامعــة انــه اســتلم املبلــغ كامــا ولــم يســلم‬\n      ‫الشــقة رقــم (‪ )3‬لوجــود خالفــات مــع الســيد صاحــب االرض وخــروج‬\n      ‫املدعــي عليــه بكفالــة ويوجــد لدينــا صــورة مــن هــذه الكفالــة املرفقــة‬\n      ‫ثالث ـاً‪ :‬هــذا الــكالم غيــر صحيــح ومرفــق يف ملــف القضيــة اعتــراف‬\n      ‫الســيد انــه اســتلم املبلــغ كامــل مــن الســيدة (‪ )........‬ولــم يســلمها الشــقة‬\n      ‫وهــي شــقه رقــم (‪ )3‬أمــا أنــه بســبب تشــابه األســماء أصبــح الســيد قريــب‬\n      ‫لــي وأن هنــاك مؤامــرة بينــي وبــن (‪ )........‬ضــد فهــذه تهمــة انــا ال اســمح‬\n      ‫بهــا واريــد مــن فضيلتكــم تســجيلها واذا ثبــت غيــر ذلــك فلــن اتنــازل عــن‬\n      ‫حقــي يف هــذه التهمــة وحتويلهــا إلــى القضــاء رابع ـاً‪ :‬فضيلــة الشــيخ‬\n      ‫(‪ )........‬اعتقــد أن الســيد(‪ )........‬ووكيلــه الشــرعي يريــد تطويــل‬\n      ‫القضيــة بــإدراج اســم ويوجــد يف ملــف القضيــة لديكــم اعتــراف امــام‬\n      ‫(‪ )........‬يف شــرطة اجلامعــة انــه اســتلم املبلــغ بالكامــل ولــم يســلم الشــقة‬\n      ‫رقــم (‪ )3‬وخــرج منهــا بكفالــة يف ذلــك الوقــت‪ .‬خامســا‪ :‬اكــرر‬\n      ‫لفضيلتكــم انــه يوجــد يف ملــف القضيــة اعتــراف انــه اســتلم املبلــغ ولــم‬\n      ‫يســلم الشــقة رقــم (‪ )3‬وجميــع الســندات مرفقــه يف هــذا اخلطــاب‪ .‬نطلــب‬\n      ‫مــن فضيلتكــم انصافنــا وقــد ُاخــذ منــي املبلــغ مــن غيــر وجــه حــق‬\n      ‫والضــرر الــذي اصابنــي مــن بيــع مــا منلــك حتــى نشــتري هــذه الشــقة ولــم‬\n\n\n‫‪289‬‬\n\f‫نســكن فيهــا غيــر املبالــغ التــي ألكثــر مــن ســنتني وانــا أدفعهــا لإليجــار‬\n‫وهــذه الشــقة قــد أفرغــت لرجــل آخــر لــذا أطلــب إلــزام املدعــى عليــه‬\n‫بدفــع املبلــغ الــذي أخــذه منــي وقــدره خمســمائة ألــف ريــال كمــا جــرى‬\n‫االطــاع علــى أوراق املعاملــة ووجــد مــن ضمنهــا ملــف إجــراءات‬\n‫االســتدالل الصــادر مــن مركــز شــرطة اجلامعــة وباالطــاع علــى اللفــة‬\n‫رقــم ‪ 12‬واملتضمنــة مــا نصــه ‪ :‬الســؤال ‪ .‬هــل أنــت تعتــرف باســتالم املبلــغ‬\n‫وقــدره خمســمائة ألــف ريــال مــن املــرأة املذكورة ؟ اجلواب ‪ .‬نعم اســتلمنا‬\n‫منهــا املبلــغ املشــار لــه أ ‪ .‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫ـاء علــى مــا ورد يف الفقــرة األولــى مــن املــادة اخلامســة واخلمســن مــن‬     ‫بنـ ً‬\n‫نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة ونصهــا‪ ( :‬إذا تبلــغ املدعــى‬\n‫عليــه لشــخصه أو وكيلــه الشــرعي يف القضيــة نفســها مبوعــد اجللســة‬\n‫أو أودع هــو أو وكيلــه مذكــرة بدفاعــه للمحكمــة قبــل اجللســة فيعــد‬\n‫احلكــم يف حقــه حضوريـ ًا ســواء أكان غيابــه قبــل قفــل بــاب املرافعــة أم‬\n‫بعــده) ومبــا أن املدعيــة ذكــرت يف دعواهــا أنهــا دفعــت للمدعــى عليــه‬\n‫مبلــغ وقــدره خمســمائة ألــف ريــال لكــي يفــرغ لهــا الشــقة رقــم (‪ )3‬يف‬\n‫حــي (‪ )........‬وأن املدعــى عليــه لــم يــف بهــذا االتفــاق وأنهــا تطلــب إلــزام‬\n‫املدعــى عليــه بإعــادة املبلــغ الــذي اســتلمه وقــدره خمســمائة ألــف ريــال‬\n‫ومبــا أن املدعــى عليــه أقــر باســتالمه مــن املدعية مبلغ ًا وقدره خمســمائة‬\n‫ألــف ريــال حســب مــا جــاء يف ملــف إجــراءات االســتدالل وألن االقــرار‬\n‫حجــة علــى املقــر وألن املــرء مؤاخــذ بإقــراره إذا صــدر منــه علــى الصفــة‬\n‫املشــروعة ومبــا أن املدعــى عليــه لــم يلتــزم بإفــراغ الشــقة للمدعيــة ومــا‬\n‫ذكــره وكيــل املدعــى عليــه مــن أن املبلــغ الــذي اســتلمه مت إفراغ الشــقة‬\n‫للمدعيــة وبقيــت شــقة أخــرى لــم تدفــع قيمتهــا فغيــر صحيــح حيــث‬\n\n\n                                                                                           ‫‪290‬‬\n\f      ‫اشــترى الشــقة األخــرى زوج بنــت املدعيــة وعــن طريــق بنــك (‪ )........‬ومت‬\n      ‫االفــراغ لــه وأمــا مــا دفعتــه املدعيــة فلــم يقــم املدعــى عليــه باإلفــراغ لهــا‬\n      ‫مــا اتفقــا عليــه وحيــث ذكــرت املدعيــة أن الشــقة املذكــورة قــد بيعــت‬\n      ‫علــى رجــل آخــر وأنهــا تطلــب إلــزام املدعــى عليــه بدفــع مــا أخــذه وجلميــع‬\n      ‫مــا تقــدم فقــد حكمــت علــى املدعــى عليــه حكمـ ًا حضوريـ ًا بــأن يدفــع‬\n      ‫للمدعيــة مبلغــا وقــدره خمســمائة ألــف ريــال حالــة بــدون مماطلــة وال‬\n      ‫تأخيــر وبعرضــه علــى املدعيــة قــررت القناعــة وأمــرت بإكمــال مــا يلــزم‬\n      ‫حيــال إبــاغ املدعــى عليــه الغائــب باحلكــم حســب املــادة (‪)4/176‬‬\n      ‫واملــادة (‪ )178‬مــن الالئحــة التنفيذيــة لنظــام املرافعــات الشــرعية وذلــك‬\n      ‫عــن طريــق محضــري اخلصــوم باحملكمــة ومــن حــن اســتالم املدعــى‬\n      ‫عليــه صــورة مــن صــك احلكــم يحســب له ثالثــون يوما إلبــداء االعتراض‬\n      ‫علــى احلكــم فــإن مضــت هــذه املــدة ولــم يقــدم اعتراضــه فإنــه يســقط‬\n      ‫حقــه يف طلــب االســتئناف ويكتســب احلكــم القطعيــة وأغلقــت اجللســة‬\n      ‫الســاعة (‪ )11:30‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                       ‫آله وصحبه وسلم ‪ .‬حرر يف ‪1434/5/20‬هـ‪.‬‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ (‪ )........‬القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد‬\n      ‫(‪ )34220791‬وتاريــخ ‪1434/5/25‬ه املتضمــن دعــوى (‪ )........‬ضــد‬\n      ‫(‪ )........‬واحملكــوم فيــه مبــا دون باطنــة وبدراســة الصــك وصــورة ضبطه‬\n      ‫والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم‪ .‬وصلــى‬\n                               ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪291‬‬\n\f                         ‫كشاف املوضوعات‬\n‫الصفحة‬                        ‫املوضوع‬                         ‫التصنيف‬   ‫م‬\n\n          ‫مطالبة املدعي للمدعى عليهما بإعادة قيمة قطع‬\n  ‫‪5‬‬                                                             ‫بيع‬     ‫‪1‬‬\n            ‫األرض للمخطط الذي تبني أنه ملك للدولة‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإعادة جزء من قيمة‬\n  ‫‪17‬‬     ‫املزرعة التي اشتراها منه ‪-‬حيث تبني له وجود الغنب‬       ‫بيع‬     ‫‪2‬‬\n               ‫يف القيمة املفروضة عليه‪ -‬أو فسخ البيع‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بدفع قيمة السيارة ورد‬\n  ‫‪28‬‬                                                            ‫بيع‬     ‫‪3‬‬\n                     ‫احملال عليه لكونه معسر ًا‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإعادة بعض قيمة‬\n  ‫‪33‬‬     ‫اإلبل التي اشتراها منه لوجود الغنب يف السعر الذي‬       ‫بيع‬     ‫‪4‬‬\n                           ‫اشتراها به‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بإعادة مبلغ العقار‬\n  ‫‪37‬‬       ‫الذي اشتراه منه بعدما تبني له أنه ال ميلك العقار‬     ‫بيع‬     ‫‪5‬‬\n                                ‫املذكور‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بأن يدفع فارق قيمة‬\n  ‫‪43‬‬     ‫العقارات التي اشتراها منه بدعوى الغنب يف السعر‬         ‫بيع‬     ‫‪6‬‬\n                         ‫الذي اشترى به‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بقيمة البضاعة التي‬\n  ‫‪50‬‬                                                            ‫بيع‬     ‫‪7‬‬\n         ‫اشتراها منه وقدم على ذلك من البينات شاهد وميينه‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإفراغ نصيبه الذي‬\n  ‫‪59‬‬                                                            ‫بيع‬     ‫‪8‬‬\n                          ‫اشتراه منه‬\n\f‫الصفحة‬                       ‫املوضوع‬                           ‫التصنيف‬   ‫م‬\n\n            ‫مطالبة املدعي للمدعى عليه بدفع باقي قيمة‬\n  ‫‪68‬‬                                                             ‫بيع‬     ‫‪9‬‬\n                    ‫السيارة التي اشتراها منه‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بفسخ العقد لعدم قدرة‬\n  ‫‪72‬‬                                                             ‫بيع‬     ‫‪10‬‬\n         ‫املدعى عليه على سداد باقي قيمة الوحدة السكنية‬\n\n\n         ‫مطالبة املدعي للمدعى عليه باستالم السيارة وإعادة‬\n  ‫‪81‬‬                                                             ‫بيع‬     ‫‪11‬‬\n                 ‫قيمتها له لوجود عيوب مصنعية فيها‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بفسخ عقد بيع السيارة‬\n  ‫‪91‬‬                                                             ‫بيع‬     ‫‪12‬‬\n                      ‫لوجود عيوب مصنعية فيها‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإعادة قيمة السيارة‬\n ‫‪112‬‬                                                             ‫بيع‬     ‫‪13‬‬\n          ‫التي اشتراها منه حيث احترقت لوجود عيب فيها‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بتسليم ما تبقى فيه‬\n ‫‪118‬‬                                                             ‫بيع‬     ‫‪14‬‬\n              ‫ذمته من قيمة األغنام التي اشتراها منه‬\n\n\n         ‫مطالبة املدعي للمدعى عليه باستالم السيارة التي‬\n ‫‪124‬‬                                                             ‫بيع‬     ‫‪15‬‬\n         ‫باعها على املدعي ورد قيمتها لوجود عيوب يف ذلك‬\n\n\n            ‫مطالبة املدعي بفسخ بيع العقار الذي مت بينه‬\n         ‫واملدعى عليه لوجود الغنب يف القيمة املقدرة له أو رد‬\n ‫‪133‬‬                                                             ‫بيع‬     ‫‪16‬‬\n         ‫الفرق يف القيمة ‪،‬باإلضافة إلى تعويضه عن األجزاء‬\n               ‫املقتطعة من األرض لصالح أمالك الدولة‬\n\n\n          ‫مطالبة املدعي بفسخ بيع السيارة لوجود الغنب يف‬\n ‫‪146‬‬     ‫القيمة ولوجود عيوب فيها لم يخبره عنها البائع وهو‬        ‫بيع‬     ‫‪17‬‬\n                            ‫املدعى عليه‬\n\f‫الصفحة‬                       ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n          ‫مطالبة املدعي بفسخ بيع العقار على املدعى عليه‬\n ‫‪151‬‬                                                          ‫بيع‬     ‫‪18‬‬\n                  ‫لتأخره عن سداد باقي القيمة‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإعادة الشاحنة التي‬\n ‫‪158‬‬                                                          ‫بيع‬     ‫‪19‬‬\n                       ‫سبق أن اشتراها منه‬\n\n\n            ‫مطالبة املدعي للمدعى عليه بدفع باقي قيمة‬\n          ‫املكيفات التي اشتراها منه ‪،‬وألزم املدعى عليه‬\n ‫‪165‬‬                                                          ‫بيع‬     ‫‪20‬‬\n          ‫بدفع ما تبقى من رأس مال السلع املباعة عليه دون‬\n          ‫األرباح ألن البائع وهو املدعي قد ربح ما لم يضمن‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بفسخ بيع العقار الذي‬\n ‫‪174‬‬     ‫باعه املدعي للمدعى عليه ليقوم بفك الرهن الواقع‬       ‫بيع‬     ‫‪21‬‬\n                               ‫عليه‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بسداد باقي قيمة أطقم‬\n ‫‪182‬‬                                                          ‫بيع‬     ‫‪22‬‬\n                  ‫الذهب التي سبق أن باعها عليه‬\n\n\n         ‫مطالبة املدعي بإثبات صحة شرائه للعقار حيث قام‬\n ‫‪193‬‬                                                          ‫بيع‬     ‫‪23‬‬\n             ‫بتسليم كامل املبلغ قبل وفاة مالك العقار‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإعادة املبلغ املدفوع‬\n ‫‪202‬‬                                                          ‫بيع‬     ‫‪24‬‬\n                           ‫مقابل شراء عقار‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بإفراغ قيمة العقارات‬\n         ‫التي اشتراها منه ودفع أتعاب احملامي ‪،‬ورد املدعى‬\n ‫‪210‬‬                                                          ‫بيع‬     ‫‪25‬‬\n          ‫عليه بأن البيع باطل لكونه وقع على العقارات‬\n                    ‫املذكورة قبل أن ميتلكها‬\n\f‫الصفحة‬                       ‫املوضوع‬                          ‫التصنيف‬   ‫م‬\n\n           ‫مطالبة املدعي للمدعى عليه بإفراغ العقار الذي‬\n            ‫اشتراه منه ‪،‬ورد املدعى عليه بأن املدفوع غير‬\n ‫‪221‬‬                                                            ‫بيع‬     ‫‪26‬‬\n           ‫ما ذكره املدعي باإلضافة إلى أن صك العقار‬\n          ‫املذكورة ممنوع التصرف فيه بأمر من احملكمة‬\n\n\n         ‫مطالبة املدعي بإلزام ورثة املدعى عليه بإعادة إفراغ‬\n         ‫األرض له لكونه سبق أن باعاها ملورثهم بيعا صوريا‬\n ‫‪230‬‬                                                            ‫بيع‬     ‫‪27‬‬\n          ‫حتى يستطيع أن يستخرج عليها قرضا من صندوق‬\n                           ‫التنمية العقارية‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بفرق سعر بيع العقار‬\n ‫‪236‬‬      ‫بسبب الضرر احلاصل بالغش والتدليس من املدعى‬            ‫بيع‬     ‫‪28‬‬\n                               ‫عليه‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بإعادة املبلغ الذي دفعه‬\n ‫‪243‬‬      ‫مقابل أرض زعم املدعى عليه أنها ملك له ولقبيلته‬        ‫بيع‬     ‫‪29‬‬\n                    ‫بصك عام ثم تبني خالف ذلك‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بإعادة العقار له ‪،‬حيث‬\n         ‫قام املدعي بتحويل مبلغ مالي للمدعى عليه ليشتري‬\n ‫‪246‬‬                                                            ‫بيع‬     ‫‪30‬‬\n           ‫له عقارا ‪،‬إال أن املدعى عليه قام بإفراغ العقار‬\n                               ‫باسمه‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بدفع القيمة احلالة‬\n ‫‪250‬‬         ‫اخلاصة بالسيارة التي اشتراها مكفوله منه‬            ‫بيع‬     ‫‪31‬‬\n               ‫وااللتزام بسداد باقي األقساط يف حينها‬\n\n\n          ‫مطالبة املدعي للمدعى عليهم بإفراغ العقار الذي‬\n ‫‪256‬‬     ‫اشتراه من موكلهم وقام بسداد كامل قيمته لكن‬             ‫بيع‬     ‫‪32‬‬\n            ‫موكلهم تويف قبل أن يفرغ العقار للمدعي‬\n\f‫الصفحة‬                      ‫املوضوع‬                         ‫التصنيف‬   ‫م‬\n\n         ‫مطالبة املدعي للمدعى عليه بإبطال عقد بيع عقار‬\n ‫‪265‬‬                                                          ‫بيع‬     ‫‪33‬‬\n             ‫للمدعي لطرف ثالث لكونه غير مالك له‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بإبطال بيع العقار الذي‬\n ‫‪273‬‬     ‫اشتراه من البائع وهو ال ميلكه ‪،‬لكون البائع سبق‬       ‫بيع‬     ‫‪34‬‬\n         ‫أن باعه على املدعي قبل أن يبيعه على املدعى عليه‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإلزامه بإعادة فرق‬\n           ‫قيمة البضاعة املشتراة منه ‪،‬حيث دفع املدعي‬\n ‫‪278‬‬                                                          ‫بيع‬     ‫‪35‬‬\n          ‫قيمتها كمؤجلة ‪،‬بينما أخدها املدعى عليه منه‬\n                           ‫بالقيمة احلالّة‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإعادة كامل املبلغ‬\n ‫‪283‬‬     ‫املدفوع مقابل شراء شقة ‪،‬لكون املدعى عليه قام‬         ‫بيع‬     ‫‪36‬‬\n                    ‫ببيع نفس الشقة لطرف آخر‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":283,"source_page_end":296,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1f6de311f8668d08fcdb7a49cb6b43f4ba88ff99dfa1a73c339f15fddcf023a6","normalized_text_hash":"8781c8ae29f88b4b8003ed5d0c52e2f60507a212e46eac271abbdab59f37f757","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p283-34220791"},{"id":"971901a0-7295-5a2b-8503-5203818d416c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي -تستر على مصدرها -إقرار -عدم إدانة بالتستر -التعزير بالسجن واملنع","document_number":"33337850","case_number":"33370838","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/07/13","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي -تستر على مصدرها -إقرار -عدم إدانة بالتستر -التعزير بالسجن واملنع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك ‪ 33337850:‬تاريخه‪1433/07/13 :‬هـ‬\n                        ‫رقم الدعوى‪33370838:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3469582‬تاريخه‪1433/05/28 :‬هـ‬\n\n\n     ‫مخــدرات‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصــد التعاطــي ‪ -‬تســتر‬\n     ‫علــى مصدرهــا‪ -‬إقــرار‪ -‬عــدم إدانــة بالتســتر‪ -‬التعزيــر بالســجن واملنــع‬\n                                                                        ‫مــن الســفر‪.‬‬\n\n\n\n\n     ‫املواد (‪ )3‬و (‪ )41‬و (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه طلــب إثبــات إدانتــه بحيــازة‬\n     ‫احلشــيش املخــدر وحبــوب اإلمفيتامــن احملظــورة بقصــد التعاطــي‬\n     ‫وتســتره علــى مصدرهــا‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن‬\n     ‫الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وعقوبــة‬\n     ‫تعزيريــة لقــاء التســتر وحيــث إنــه قــد مت تفتيــش الســيارة التــي كان‬\n     ‫يركبهــا فعثــر فيهــا علــى نصــف حبــة يشــتبه أن تكــون مــن احلبــوب‬\n     ‫احملظــورة‪ ،‬ومت تفتيشــه شــخصيا فعثــر علــى قطعــة يشــتبه أن تكــون‬\n     ‫مــن احلشــيش املخــدر مخفيــة باجلــورب األميــن الــذي كان يرتديــه‪،‬‬\n     ‫أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش‬\n     ‫املخــدر واإلمفيتامــن‪ ،‬أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي‬\n     ‫العــام وأنكــر تســتره علــى مصدرهــا واســتعد بالداللــة عليــه‪ ،‬قضــت‬\n\n‫‪5‬‬\n\f‫احملكمــة بإدانــة املدعــى عليــه بحيــازة احلشــيش املخــدر واحلبــوب‬\n‫احملظــورة بقصــد التعاطــي وصرفــت النظــر عــن تعزيــر املدعــى عليــه‬\n‫لقــاء تســتره علــى مصــدر املخــدر وحكمــت بســجنه ملــدة ســتة أشــهر‬\n‫ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني‪ ،‬عــارض املدعــى عليــه‬\n‫واملدعــي العــام علــى احلكــم و قــررت محكمــة االســتئناف املصادقــة‬\n                                                            ‫علــى احلكــم‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة اخلــرج بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باخلــرج املســاعد برقــم ‪ 33370838‬وتاريــخ‬\n‫‪1433/06/01‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331020067‬وتاريــخ‬\n‫‪1433/06/01‬ه ـ ففــي يــوم الســبت املوافــق ‪1433/07/12‬ه ـ فتحــت‬\n‫اجللســة الســاعة وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق واالدعــاء‬\n‫العــام مبحافظــة اخلــرج وادعــى علــى احلاضــر معــه يف املجلــس الشــرعي‬\n‫‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ................‬قائــا‬\n‫يف حتريــر دعــواه عليــه بصفتــي مدعيـ ًا عامـ ًا بدائــرة التحقيــق واالدعــاء‬\n‫العــام مبحافظــة اخلــرج أدعــي علــى‪ ، .................... -:‬البالــغ مــن العمــر‬\n‫(‪ )24‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة رقــم‬\n‫(‪ ).....................‬متعلــم ‪ ،‬موظــف قطــاع خــاص ‪ ،‬يقيــم مبحافظــة اخلرج‪،‬‬\n‫أوقــف بتاريــخ ‪1433/3/27‬ه ـ وأفــرج عنــه بضمــان محــل اإلقامــة بتاريــخ‬\n‫‪1433/3/28‬ه ـ اســتناد ًا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n‫حيــث إنــه بتاريــخ ‪1433/3/27‬ه ـ قبــض علــى املدعــى عليــه مــن قبــل‬\n\n                                                                                        ‫‪6‬‬\n\f    ‫إحــدى فــرق القــوة اخلاصــة ألمــن الطــرق مبدينــة الريــاض اثــر االشــتباه‬\n    ‫بســيارة مــن نــوع ‪ ...‬بقيــادة‪ ........‬ويرافقــه ‪ُ ( ........‬أخلــي ســبيلهما مــن‬\n    ‫قبــل الفرقــة القابضــة لعــدم عالقتهمــا مبــا ضبــط اســتناد ًا للمــادة (‪)34‬‬\n    ‫مــن نظــام اإلجــراءات اجلزائيــة) املدعــى عليــه وبتفتيــش الســيارة وجــد‬\n    ‫مبرتبــة الراكــب علــى علبــة دخــان بهــا نصــف حبــة يشــتبه أن تكــون‬\n    ‫مــن احلبــوب احملظــورة وبتفتيــش املدعــى عليــه عثــر علــى قطعــة يشــتبه‬\n    ‫أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )3.4‬ثالثــة جرامــات وأربعــة‬\n    ‫أعشــار اجلــرام كانــت مخفيــة باجلــورب األميــن الــذي كان يرتديــه‬\n    ‫وقــد أقــر بعائديــة املضبوطــات لــه (ودون لــه إقــرار بذلــك )‪ .‬وقــد أثبــت‬\n    ‫التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة الســموم‬\n    ‫والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم (‪........‬لعــام ‪1433‬ه ـ‬\n    ‫احتــواء نصــف احلبــة املضبوطــة لإلمفيتامــن وهــو مــن املــواد املنبهــة‬\n    ‫واملدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات‬\n    ‫واملؤثــرات العقليــة وإيجابيــة عينــة القطعــة املضبوطــة ملــادة احلشــيش وهو‬\n    ‫مــن املــواد املخــدرة واملدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام‬\n    ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وبســماع أقوالــه األوليــة أقــر‬\n    ‫بحيــازة نصــف احلبــة وقطعــة احلشــيش املخــدر املضبوطتــن ولــم يــدل‬\n    ‫مبعلومــات عــن مصــدر مــا ضبــط‪ .‬وقــد انتهــى التحقيــق معــه إلــى توجيــه‬\n    ‫االتهــام لــه بحيــازة نصــف حبــة مــن حبــوب اإلمفيتامــن املنبهــة احملظــورة‬\n    ‫وقطعــة مــن احلشــيش املخــدر تــزن (‪ )3.4‬ثالثــة جرامــات وأربعــة أعشــار‬\n    ‫اجلــرام بقصــد التعاطــي املجــرم مبوجــب الفقــرة(‪ )2‬مــن املــادة ( الثالثــة‬\n    ‫) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n    ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر مــا‬\n\n\n‫‪7‬‬\n\f‫ضبــط املعاقــب علــى ذلــك شــرع ًا وفق ـ ًا لقــرار االتهــام املرفــق رقــم (ه ـ‬\n‫ر ‪ )933/5/1‬لعــام ‪1433‬ه ـ وذلــك لألدلــة والقرائــن التاليــة‪ -1 -:‬مــا‬\n‫تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنــوه عنــه املــدون علــى‬\n‫الصفحــة رقــم (‪ )3‬مــن ملــف ضبــط إجــراءات االســتدالل يف قضايــا‬\n‫املخــدرات املرفــق لفــة رقــم (‪ -2 .)1‬إقــراره لــدى الفرقــة القابضــة املنــوه‬\n‫عنــه واملرفــق لفــة رقــم (‪ -3 .)3‬مــا تضمنــه محضــر القبــض املنــوه عنــه‬\n‫املرفــق لفــة رقــم (‪ -4 .)4‬مــا تضمنــه التقريــر الكيميائــي الشــرعي‬\n‫املنــوه عنــه املرفــق لفــة رقــم (‪ .)23‬وببحــث ســوابقه اتضــح عــدم وجــود‬\n‫ســوابق مســجلة عليــه حتــى تاريخــه‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى‬\n‫عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه‬\n‫شــرع ًا ونظام ـ ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n‫باآلتــي‪ -1 -:‬بعقوبــة وفقـ ًا ملــا ورد بالفقــرة (األولــى ) مــن املــادة (‪ )41‬مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء مــا أســند إليــه‪-2 .‬‬\n‫منعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة ســجنه‬\n‫وفق ـ ًا للفقــرة ( األولــى) مــن املــادة (‪ )56‬مــن نفــس النظــام املشــار إليــه‪.‬‬\n‫‪ -3‬بعقوبــة تعزيريــة لقــاء تســتره علــى مصــدر مــا ضبــط اســتناد ًا لتعميــم‬\n‫صاحــب الســمو امللكــي أميــر منطقــة الريــاض بالنيابــة رقــم (‪)10283‬‬\n‫وتاريــخ ‪1430/5/17‬هــ‪ .‬هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى‬\n‫املدعــي العــام أجــاب قائــا إن مــا ذكــره املدعــي العــام يف دعــواه كلــه‬\n‫صحيــح جملــة وتفصيــا فقــد مت القبــض علــي بتاريــخ ‪1433/3/27‬ه ـ‬\n‫مــن قبــل دوريــات أمــن الطــرق بينمــا كنــت راكبــا مــع زميلــي‪........‬‬\n‫و‪ ........‬وعثــر بحوزتــي علــى نصــف حبــة مــن احلبــوب احملظــورة وقطعــة‬\n‫مــن احلشــيش املخــدر وزنهــا ثالثــة جرامــات وأربعــة أعشــار اجلــرام‬\n\n\n                                                                                         ‫‪8‬‬\n\f    ‫كنــت أنــوي اســتعمالها‪ ،‬ولــم يســبق لــي التعاطــي مــن قبــل ‪ ،‬وبالنســبة‬\n    ‫ملــا ذكــره املدعــي العــام مــن تســتري علــى املصــدر فغيــر صحيــح فأنــا‬\n    ‫لــم أتســتر علــى املصــدر ومصدرهــا معــروف لــدي ومســتعد بالتعــاون‬\n    ‫مــع اجلهــات املختصــة مــن أجــل إبالغهــم باســمه وعنوانــه فأنــا أعــرف‬\n    ‫اســمه كامــا وعنــوان ســكنه أيضــا‪ ،‬هــذا مــا لــدي ثــم جــرى منــا‬\n    ‫االطــاع علــى كامــل أوراق املعاملــة فوجــد مــن ضمنهــا أقــوال املدعــى‬\n    ‫عليــه حتقيقــا املدونــة علــى ملــف التحقيــق املرفــق علــى لفــة رقــم (‪)1‬‬\n    ‫صحيفــة رقــم (‪ )3‬واملتضمــن إقــراره بعائديــة احلشــيش املخــدر ونصــف‬\n    ‫احلبــة مــن الكبتاجــون لــه وعنــد ســؤاله عــن مصدرهــا أفــاد بأنــه ال‬\n    ‫يعــرف املصــدر وبعــرض ذلــك علــى املدعــي عليــه قــال بالنســبة للمصــدر‬\n    ‫فأنــا أعرفــه ومســتعد بالداللــة عليــه كمــا ذكــرت ســابقا ومــا ذكــره‬\n    ‫احملقــق علــى لســاني مــن أننــي ال أعــرف املصــدر غيــر صحيــح بــل كان‬\n    ‫احملقــق يكتــب الســؤال واجلــواب وال يســألني هــذا مــا لــدي كمــا جــرى‬\n    ‫االطــاع علــى إقــرار املدعــى عليــه املــدون علــى لفــة رقــم (‪ )3‬مــن املعاملــة‬\n    ‫لــدى إدارة مكافحــة املخــدرات بعائديــة احلشــيش ونصــف احلبــة لــه‬\n    ‫وبعرضــه عليــه صــادق عليــه كمــا جــرى االطــاع علــى محضــر القبــض‬\n    ‫املرفــق علــى لفــة رقــم (‪ )4‬وبعرضــه علــى املدعــى عليــه صــادق عليــه‬\n    ‫كمــا جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي الصــادر مــن‬\n    ‫مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض برقــم‬\n    ‫‪........‬وتاريــخ ‪1433/4/12‬ه ـ واملتضمــن إيجابيــة العينــة األولــى ملــادة‬\n    ‫اإلمفيتامــن وإيجابيــة العينــة الثانيــة ملــادة احلشــيش وهمــا مــن املــواد‬\n    ‫املدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) وباجلــدول رقــم (‪ )1‬فئــة (أ) مــن‬\n    ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبعرضــه علــى املدعــى‬\n\n\n‫‪9‬‬\n\f‫عليــه صــادق عليــه ‪ ،‬وبســؤال املدعــى عليــه هــل لديــه ســوابق جنائيــة‬\n‫قــال ليــس لــدي ســوابق جنائيــة وهلل احلمــد ‪ ،‬ثــم جــرى ســؤال الطرفــن‬\n‫هــل لديهمــا مــا يضيفانــه فقــاال ليــس لدينــا مــا نضيفــه فبنــاء علــى مــا‬\n‫تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه ونظــرا إلقــراره‬\n‫بحيــازة قطعــة احلشــيش املخــدر التــي تــزن ثالثــة جرامــات وأربعــة أعشــار‬\n‫اجلــرام ونصــف حبــة مــن حبــوب الكبتاجــون بقصــد االســتعمال‪ ،‬وبعــد‬\n‫االطــاع علــى التقريــر الكيميائــي الشــرعي والــذي تضمــن إيجابيــة‬\n‫العينــة للحشــيش املخــدر ومــادة اإلمفيتامــن وهمــا مــن املــواد املخــدرة‬\n‫املدرجــة يف جــداول نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪،‬‬\n‫وبعــد االطــاع علــى محضــر القبــض علــى املدعــى عليــه وبنــاء علــى املــادة‬\n‫الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبنــاء علــى‬\n‫املــادة احلاديــة واألربعــن واملــادة السادســة واخلمســن مــن ذات النظــام ‪،‬‬\n‫وحيــث أنكــر املدعــى عليــه تســتره علــى مصــدر املضبوطــات التــي معــه‬\n‫واســتعد بالداللــة علــى مصــدر احلشــيش واحلبــوب احملظــورة والتعــاون‬\n‫مــع اجلهــات املختصــة يف ســبيل ذلــك ‪ ،‬لــكل مــا تقــدم فقــد ثبــت لــدي‬\n‫حيــازة املدعــى عليــه لقطعــة مــن احلشــيش املخــدر تــزن ثالثــة جرامــات‬\n‫وأربعــة أعشــار اجلــرام ونصــف حبــة مــن حبــوب الكبتاجــون احملظــورة‬\n‫بقصــد االســتعمال وقــررت مــا يلــي‪ :‬أوال ‪ /‬تعزيــر املدعــى عليــه لقــاء‬\n‫حيازتــه لقطعــة احلشــيش املخــدر ونصــف احلبــة بســجنه ســتة أشــهر مــن‬\n‫تاريــخ إيقافــه يف هــذه القضيــة‪ .‬ثانيــا ‪ /‬منــع املدعــى عليــه مــن الســفر‬\n‫خــارج اململكــة مــدة ســنتني بعــد انتهــاء محكوميتــه‪ .‬ثالثــا‪ /‬صرفــت‬\n‫النظــر عــن دعــوى املدعــي العــام فيمــا يتعلــق بتعزيــر املدعــى عليــه لقــاء‬\n‫تســتره علــى املصــدر‪ .‬ومبــا تقــدم حكمــت وبعرضــه علــى الطرفــن‬\n\n\n                                                                                      ‫‪10‬‬\n\f     ‫قــررا عــدم القناعــة فجــرى إفهامهمــا بأنــه ســيجري تســليمهما نســخة‬\n     ‫مــن احلكــم بتاريــخ ‪1433/7/14‬ه ـ لتقــدمي اعتراضهمــا عليــه يف مــدة‬\n     ‫أقصاهــا ثالثــون يومــا مــن تاريخــه ثــم قــرر املدعــي العــام اعتراضــه علــى‬\n     ‫احلكــم بــدون الئحــة اعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n     ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/07/12‬هــ‪ .‬احلمــد‬\n     ‫هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/02/23‬ه ـ فتحــت‬\n     ‫اجللســة بنــاء علــى خطــاب فضيلــة رئيــس محكمــة االســتئناف بالريــاض‬\n     ‫املســاعد رقــم ‪ 332074366‬وتاريــخ ‪1434/2/13‬ه ـ واملرفــق بــه قــرار‬\n     ‫أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة رقــم ‪3427337‬‬\n     ‫وتاريــخ ‪1434/2/2‬ه ـ واملتضمــن مــا نصــه‪ »:‬وبدراســة القــرار وصــورة‬\n     ‫ضبطــه وأوراق املعاملــة قررنــا باألكثريــة إعادتهــا ملالحظــة اآلتــي‪ :‬أن‬\n     ‫التعزيــر احملكــوم بــه كثيــر لقلــة الكميــة احملــازة وعــدم وجــود ســوابق‬\n     ‫واألولــى معاملتــه مبوجــب املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات‬\n     ‫واهلل املوفــق‪ .‬عليــه أجيــب أصحــاب الفضيلــة حفظهــم اهلل تعالــى أن‬\n     ‫احلكــم ليــس بكثيــر بــل كان وفقــا للحــد األدنــى مــن العقوبــة املقــررة‬\n     ‫علــى حيــازة املخــدرات ولــم يظهــر لنــا مــا يقتضــي التخفيــف علــى املدعــى‬\n     ‫عليــه طبقــا للمــادة املذكــورة وال يخفــى علــى أصحــاب الفضيلــة انتشــار‬\n     ‫هــذه اآلفــة يف املجتمــع بشــكل الفــت للنظــر والشــك أن العقوبــات‬\n     ‫الرادعــة هــي مــن أكبــر األســباب بعــد توفيــق اهلل للحــد مــن هــذا البــاء‬\n     ‫وبالتالــي فالزلــت علــى مــا حكمــت بــه وقــررت إعــادة املعاملــة حملكمــة‬\n     ‫االســتئناف حســب التعليمــات وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                           ‫نبينــا محمــد‪ .‬حــرر يف ‪1434/2/23‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n\n\n‫‪11‬‬\n\f‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باخلــرج املكلــف برقــم‬\n‫‪ 34399161‬وتاريــخ ‪1434/3/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــه القاضــي باحملكمــة الشــيخ ‪ ..../‬املســجل برقــم ‪3333785‬‬\n‫وتاريــخ ‪1433/7/13‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ ..../‬التهامه‬\n‫بقضيــه مخــدرات علــى النحــو املوضــح بالقرار املتضمــن حكم فضيلته‬\n‫مبــا هــو مــدون ومفصــل بــه ‪ .‬وحيــث ســبق دراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه علــى‬\n‫قــرار الدائــرة رقــم ‪ 3427337‬وتاريــخ ‪1434/02/02‬ه ـ قررنــا املصادقــة‬\n‫علــى احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n                                                                               ‫‪12‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":5,"source_page_end":12,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"386b7723947bca497f0c3d30c3d7918bb713e04bb156666df1d6a2bfa31a0b58","normalized_text_hash":"1a1743590bad92dc7dbf18e8797a83b118205568cb20df44a3b413fd5a74341a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p5-33337850"},{"id":"ea284300-7955-53f5-bd1b-8ace071095dd","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد الترويج وتعاطيها والشروع يف ترويجها وتستر على حيازتها-هروب من رجال األمن- إقرار -إثبات بالقرائن -عدم إدانة بالشروع -نزول عن احلد األدنى للعقوبة -انقضاء الدعوى العامة بالعفو.","document_number":"33354788","case_number":"33402724","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم بعد اإليضاح األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/06/5","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد الترويج وتعاطيها والشروع يف ترويجها وتستر على حيازتها-هروب من رجال األمن- إقرار -إثبات بالقرائن -عدم إدانة بالشروع -نزول عن احلد األدنى للعقوبة -انقضاء الدعوى العامة بالعفو.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 33354788 :‬تاريخه‪1433/06/5 :‬هـ‬\n                          ‫رقم الدعوى‪33402724:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 349320‬تاريخه‪1434/01/12:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد الترويــج وتعاطيهــا‬\n      ‫والشــروع يف ترويجهــا وتســتر علــى حيازتها‪-‬هــروب مــن رجــال األمــن‪-‬‬\n      ‫إقــرار‪ -‬إثبــات بالقرائــن‪ -‬عــدم إدانــة بالشــروع‪ -‬نــزول عــن احلــد األدنــى‬\n                                  ‫للعقوبــة‪ -‬انقضــاء الدعــوى العامــة بالعفــو‪.‬‬\n\n\n\n\n       ‫‪ -1‬قول اهلل تعالى‪ (( :‬وال تلقوا بأيديكم إلى التهلكة )) البقرة‪.195:‬‬\n                               ‫‪ -2‬املواد (‪ )22‬من نظام اإلجراءات اجلزائية‪.‬‬\n      ‫‪ -3‬املــواد (‪ )38( )3‬و(‪ )53‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات‬\n                                                       ‫واملؤثــرات العقليــة‪.‬‬\n\n\n\n      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليهــم تتضمــن طلــب إثبــات إدانــة‬\n      ‫الثالــث بحيــازة حبــة مــن حبــوب اإلمفيتامــن احملظــورة بقصــد الترويــج‬\n      ‫وشــروعه يف ترويجهــا وتعاطيــه مــن نوعهــا وإدانــة الثانــي والثالــث‬\n      ‫بالتســتر علــى حيــازة األول للمخــدر وإدانــة املدعــى عليهــم بالهــروب مــن‬\n      ‫رجــال األمــن‪ ،‬واحلكــم علــى الثالــث بعقوبــة الســجن واجللــد والغرامــة‬\n      ‫واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫وبعقوبــة تعزيريــة لهــم علــى باقــي التهــم‪ ،‬مت االتفــاق مــع الثالــث علــى‬\n\n‫‪13‬‬\n\f‫شــراء حبــوب محظــورة فوافــق علــى ذلــك ويف الوقــت واملــكان احملددين‬\n‫حضــر ومعــه األول والثانــي وملــا شــعروا بوجــود رجــال األمــن الذوا‬\n‫بالفــرار فقبــض عليهــم وبتفتيــش الثالــث شــخصيا عثــر بجيبــه علــى‬\n‫حبــة محظــورة‪ ،‬أثبــت التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة‬\n‫املرســلة لإلمفيتامــن‪ ،‬أقــر الثالــث أمــام احملكمــة بتعاطــي احلبــوب‬\n‫احملظــورة وبحيازتــه حلبــة محظــورة بقصــد التعاطــي وأنكــر أن يكــون‬\n‫قصــده الترويــج كمــا أنكــر بقيــة املدعــى عليهــم التهــم املنســوبة لهــم‪،‬‬\n‫طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه وقــررت ســماع شــهادة‬\n‫شــهود محضــر القبــض فشــهدوا مبــا يثبــت دعــوى املدعــي فيمــا يخــص‬\n‫احليــازة بقصــد الترويــج فقــط‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه‬\n‫الثالــث بتعاطــي احلبــوب احملظــورة وحيازتهــا بقصــد الترويــج وقــررت‬\n‫جلــده ســتني جلــدة دفعــة واحــدة وســجنه ملــدة ســتة أشــهر وتغرميــه مبلــغ‬\n‫ألــف ريــال ومنعــه مــن الســفر مــدة ســنتني ومصــادرة املضبوطــات‪ ،‬كمــا‬\n‫قضــت بــرد طلــب املدعــي العــام إدانــة املدعــى عليــه الثالــث بالشــروع يف‬\n‫الترويــج والهــروب مــن رجــال األمــن لعــدم ثبوتهــا‪ ،‬وقضــت بــرد طلــب‬\n‫املدعــي العــام معاقبــة باقــي املدعــى عليهــم النقضــاء الدعــوى بحقهمــا‬\n‫بعفــو ولــي األمــر‪ ،‬قنــع املدعــى عليــه الثالــث باحلكــم وعــارض املدعــي‬\n‫العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم بعــد‬\n                                                              ‫اإليضــاح األخيــر‪.‬‬\n\n\n\n\n                                                                                    ‫‪14‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬رئيــس احملكمــة اجلزئيــة‬\n     ‫مبحافظــة القطيــف ففــي يــوم الســبت املوافــق ‪1432/2/18‬ه ـ حضــر‬\n     ‫املدعــي العــام وحضــر حلضــوره املدعــى عليــه الثالــث واملوقــوف‬\n     ‫بتاريخ‪1431/11/1‬ه ـ واحملــال لســجن محافظــة القطيــف ولــم يحضــر‬\n     ‫املدعــى عليهمــا األول ‪ ........‬ســعودي رقــم ســجله املدنــي (‪ ).........‬و‬\n     ‫الثانــي ‪ ........‬ســعودي رقــم ســجله املدنــي (‪ ).....‬رغــم تبلــغ األول مبوعــد‬\n     ‫اجللســة بتاريــخ ‪1432/1/22‬ه ـ عــن طريــق مأمــور اإلحضــار باحملكمــة‬\n     ‫ا إنــه مت االتصــال والتنســيق واالتفــاق بــن املدعــى‬      ‫وادعــى األول قائ ـ ً‬\n     ‫عليــه الثالــث وبــن املصــدر بواســطة الهاتــف اجلــوال رقــم (‪ ).....‬وعلــى‬\n     ‫مســمع مــن أحــد رجــال فرقــة مكافحــة املخــدرات علــى بيــع حبــوب‬\n     ‫مخــدرة مببلــغ مائــة ريــال وقــد حــدد املدعــى عليــه مــكان االســتالم‬\n     ‫والتســليم علــى أن يكــون يف بوفيــة بال ـ (‪ ).....‬بالقــرب مــن (‪ ).....‬وبالفعــل‬\n     ‫عنــد وصــول املصــدر إلــى املــكان املتفــق عليــه حضــر املدعــى عليــه‬\n     ‫ومعــه شــخصني واقتربــوا مــن ســيارة املصــدر وعندمــا شــعروا بوجــود‬\n     ‫رجــال مكافحــة املخــدرات الذوا بالفــرار وعنــد القبــض عليهــم‬\n     ‫وتفتيشــهم عثــر علــى حبــة أثبــت التقريــر الكيمــاوي الشــرعي‬\n     ‫رقــم(‪ 4079‬ك ش)وتاريخ‪1431/11/8‬ه ـ إيجابيتهــا ملــادة اإلمفيتامــن‬\n     ‫املنبهــة بداخــل باكــت دخــان كان بجيــب املدعــى عليــه وبالقبــض علــى‬\n     ‫الشــخصني اللذيــن ارتكبــا الفــرار معــه اتضــح أن أحدهــم املدعــى عليــه‬\n     ‫الثانــي واآلخــر املدعــى عليــه األول وباســتجواب املدعــى عليــه الثالــث‬\n     ‫اعتــرف بأنــه طلــب مــن املصــدر بــأن يحضــر لــه وأن املصــدر اتصــل عليــه‬\n\n‫‪15‬‬\n\f‫وكان يريــد حبــوب وقــال لــه عنــدك وأجابــه بقولــه نعــم تعــال و أن احلبــة‬\n‫تعــود لــه بقصــد التعاطــي وأنــه طلــب مــن املصــدر احلضــور وأنــه يتعاطــى‬\n‫احلبــوب املنبهــة وأنــه يحــوز الهاتــف نفســه الــذي متــت املكاملــة مــن خاللــه‬\n‫واالتفــاق بينــه وبــن املصــدر وباســتجواب املدعــى عليــه أفــادا بأنهمــا‬\n‫ذاهبــن إلــى البوفيــة مــن أجــل العشــاء وحضــر شــخص ذهب إليــه املدعى‬\n‫عليــه الثالــث وبعــد ذلــك قبــض عليهــم ولــم يهربــا وقــد انتهــى التحقيــق‬\n‫إلــى توجيــه االتهــام للمدعــى عليهــم بحيــازة املدعــى عليــه الثالــث حبــة‬\n‫واحــدة مــن احلبــوب املنبهــة احملظــورة بقصــد الترويــج والشــروع بترويجها‬\n‫وتعاطيــه لنوعهــا وتســتر املدعــى عليــه الثانــي واألول علــى املدعــى عليــه‬\n‫الثالــث الــذي بحوزتــه املخــدرات وهروبهــم جميع ـ ًا مــن رجــال الضبــط‬\n‫اجلنائــي وذلــك لألدلــة والقرائــن املوضحــة يف الالئحــة وبالبحــث عمــا اذا‬\n‫كان لهــم ســوابق لــم يعثــر لهــم علــى ســوابق جنائيــة مســجلة علــى‬\n‫املســتوى العــام وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب مــا‬\n‫يلــي‪-:‬أوالً‪ :‬اثبــات حيــازة املدعــى عليــه الثالــث حبــة واحــدة مــن احلبــوب‬\n‫املنبهــة واحملظــورة بقصــد الترويــج والشــروع بترويجهــا وتعاطــي احلبــوب‬\n‫املخــدرة وفــق للفقرة(‪)2‬والفقرة(‪)7‬مــن املادة(‪)3‬مــن نظــام مكافحــة‬\n‫املخــدرات واحلكــم عليــه مبــا يلــي‪ -:‬أوالً‪ :‬بعقوبــة الســجن واجللــد‬\n‫والغرامــة وفــق الفقرة(‪)1‬مــن املــادة (‪)38‬مــن النظــام ومراعــاة الفقــرة‬\n‫(‪)1‬مــن املــادة (‪)62‬مــن النظــام بشــأن العقوبــة األشــد‪-2 .‬منعــه مــن‬\n‫الســفر وفــق الفقرة(‪)1‬مــن املادة(‪)56‬مــن النظام املشــار إليه‪-3 .‬مصادرة‬\n‫هاتفــه اجلــوال الســتخدامه باجلرميــة وفــق الفقــرة رقم(‪)1‬مــن املــادة(‪)53‬‬\n‫مــن النظــام ورقمــه املصنعي(‪).‬وعــدم صــرف شــريحة اجلــوال املســتخدم‬\n\n\n                                                                                        ‫‪16‬‬\n\f     ‫لنفــس املتهــم وفق ـ ًا لتعميــم ســمو وزيــر الداخليــة رقــم(‪)9798‬‬\n     ‫وتاريخ‪1429/2/10‬هــ‪ .‬ثاني ـاً‪ :‬هروبهــم مــن رجــال الضبــط اجلنائــي‬\n     ‫وتســتر املدعــى عليهمــا م علــى املدعــى عليــه الثالــث بحيــازة املخــدرات‬\n     ‫واحلكــم عليهــم بعقوبــة تعزيريــة تزجرهــم وتــردع غيرهــم والتشــديد‬\n     ‫علــى املدعــى عليــه الثالــث وفــق الفقرة(ج)مــن املادة(‪)38‬مــن النظــام‬\n     ‫لكــون املــادة احملــازة حبــوب مخــدرة هــذه دعــواي وبعرضهــا علــى‬\n     ‫ا مــا ذكــره املدعــي العــام مــن اتصــال‬   ‫املدعــى عليــه احلاضــر أجــاب قائـ ً‬\n     ‫أحــد األشــخاص بــي علــى هاتفــي ذي الرقــم املشــار إليــه أعــاه صحيــح‬\n     ‫أمــا مــا ذكــره مــن اتفاقــي معــه علــى بيــع حبــوب مخــدرة فغيــر صحيــح‬\n     ‫والصحيــح أنــه ســألني عــن مــكان وجــودي فأخبرتــه أننــي ذاهــب لتناول‬\n     ‫العشــاء رفقــة املدعــى عليهمــا اآلخريــن عنــد بوفيــه فقــال ســأحضر لــك‬\n     ‫ا حضــر ثــم داهمتنــا فرقــة املكافحــة ولــم أهــرب منهــم وقــد عثــر‬     ‫وفعـ ً‬\n     ‫بحوزتــي علــى حبــة واحــدة مــن احلبــوب املنبهــة احملظــورة وهــي تعــود لــي‬\n     ‫بقصــد االســتعمال الشــخصي وأنــا أتعاطــى هــذه احلبــوب بســبب ظــروف‬\n     ‫عملــي التــي تســتدعي الــدوام الليلــي هكــذا أجــاب وأثنــاء اجللســة حضر‬\n     ‫املدعــى عليهمــا وبعــرض الدعــوى عليهمــا أجــاب كل واحــد منهمــا‬\n     ‫ا مــا ذكــره املدعــي العــام مــن اتفــاق املدعــى عليــه مــع أحــد‬\n                                                                          ‫مبفــرده قائـ ً‬\n     ‫مصادرهــم عــن طريــق الهاتــف علــى بيــع حبــوب محظــورة وأنــه واعــده‬\n     ‫عنــد البوفيــه ال علــم لــي بــه هكــذا أجابــا فجــرى ســؤال املدعــي العــام‬\n     ‫ألديــه بينــة علــى دعــواه قــال نعــم وهــي ‪-1‬محضــر القبــض املــدون علــى‬\n     ‫الصفحتــن رقم(‪)3-2‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم(‪.)1‬‬\n     ‫‪-2‬ماجــاء بأقــوال املدعــى عليهــم املنــوه فيهــا املدونــة علــى الصفحــات‬\n     ‫رقم(‪)7-1‬مــن دفتــر التحقيــق لفــة رقــم(‪-3 .)7‬التقريــر الكيمــاوي‬\n\n\n‫‪17‬‬\n\f‫الشــرعي رقــم(‪ 4079‬ك ش)وتاريخ‪1431/7/8‬ه ـ املرفــق باللفــة‬\n‫رقــم(‪.)12‬ويف جلســة أخــرى بتاريخ‪1432/3/24‬ه ـ حضــر املدعــي العــام‬\n‫واملدعــى عليهمــا ولــم يحضــر املدعــى عليــه وبتصفــح املعاملــة جــرى‬\n‫االطــاع علــى محضــر القبــض املشــار إليــه يف اجللســة املاضيــة فوجدتــه‬\n‫يتضمــن أنــه مت متكــن املصــدر مــن االتصــال علــي علــى الرقــم(‪)........‬‬\n‫علــى مســمع مــن اجلنــدي فقــال املصــدر أبــي أغــراض فأجــاب أشــوف‬\n‫الرجــال وأكلمــه وبعــد عشــر دقائــق ورد اتصــال مــن للمصــدر يقــول‬\n‫فيــه األغــراض موجــوده تعــال لــي يف البوفيــه التــي بجــوار (‪ ).....‬كمــا‬\n‫تضمــن احملضــر وقــوف الســيارة بجــوار البوفيــه املذكــورة وتقــدم ثالثــة‬\n‫أشــخاص أحدهــم وقــف علــى شــباك الســائق وأحدهــم بجانــب بــاب‬\n‫الراكــب وآخــر بجوارهــا يراقــب وخوف ـ ًا مــن هروبهــم النكشــاف‬\n‫ســيارة الفرقــة ثــم االقتــراب منهــم وقــام الثالثــة بالهــرب داخــل احلــي‬\n‫املظلــم وبضبطهــم عثــر يف جيــب بنطــال علــى بكــت دخــان بداخلــه حبــة‬\n‫واحــدة يشــتبه أن تكــون مــن حبــوب الكبتاجــون احملظــورة ولــم يتــح‬\n‫الوقــت الــكايف لعمليــة االســتالم والتســليم ولــم يعثــر علــى اجلــوال‪ .‬كما‬\n‫جــرى االطــاع علــى أقــوال املدعــى عليــه حتقيقـ ًا فوجدتهــا تتضمــن س‪/‬‬\n‫هــذا املــكان هــو نفســه الــذي اتفقــت مــع املصــدر ملقابلتــه فيــه؟ ج‪/‬هــو‬\n‫اتصــل علــي وكان يريــد حبــوب وقــال عنــدك فقلــت لــه نعــم تعــال‪ .‬س‪/‬‬\n‫هــل كنــت تريــد تســليمه احلبــة التــي ضبطــت بحوزتــك؟ ج‪/‬ال فقــط قلــت‬\n‫لــه تعــال‪ .‬كمــا جــرى االطــاع علــى أقــوال املدعــى عليهمــا فوجدتهــا‬\n‫تتضمــن نفــي علمهــم بوجــود احلبــوب مــع املدعــى عليــه ونفــى الهــرب‬\n‫ونفــي علمهــم بــأن يبيــع احلبــوب كمــا جــرى االطــاع علــى التقريــر‬\n‫الكيمــاوي املشــار إليــه بالدعــوى وبعــرض مــا تضمنــه محضــر القبــض‬\n\n\n                                                                                   ‫‪18‬‬\n\f     ‫ا مــا تضمنــه احملضــر مــن اتصــال املصدر‬      ‫علــى املدعــى عليــه أجــاب قائـ ً‬\n     ‫بــي علــى اجلــوال املذكــور صحيــح لكنــه لــم يكــن يســئل عــن حبــوب‬\n     ‫وأخبرتــه أننــي بال ـ (‪ ).....‬متجــه للبوفيــه ثــم اتصلــت بــه بعــد عشــر دقائــق‬\n     ‫تقريبـ ًا وقلــت لــه وينــك مــا جيــت فقــال أنــه قريــب ثــم حضــر ومــا تضمنــه‬\n     ‫احملضــر مــن قيــام املدعــى عليهمــا باملراقبــة وكــذا مــا ذكر مــن هروبنا‬\n     ‫داخــل احلــي فإنــه غيــر صحيــح ولــم أهــرب وإمنــا الــذي هــرب هــو واجلــوال‬\n     ‫ا‬ ‫الــذي جــرى االتصــال منــه صــادره أعضــاء الفرقــة أثنــاء القبــض وفعـ ً‬\n     ‫لــم يكــن املدعــى عليهمــا علــى علــم باالتصــاالت التــي متــت وال بحيازتــي‬\n     ‫للحبــة احملظــورة وبطلــب ســماع شــهادة الفرقــة حضــر ‪ ........‬ســعودي رقم‬\n     ‫ســجله املدنــي (‪ )......‬وعــرف بنفســه بأنــه يعمــل رقيــب بــإدارة مكافحــة‬\n     ‫املخــدرات وباستشــهاده قــال أشــهد أننــي قــد حضــرت مــع أعضــاء‬\n     ‫الفرقــة يف املوقــع املذكــور وشــاهدت املصــدر حضــر للموقــع لوحــده‬\n     ‫يقــود ســيارة صغيــرة أظنهــا (‪ ).....‬وتوقــف وحضــر لــه ثالثــة أشــخاص‬\n     ‫أحدهــم وقــف عنــد بــاب الســائق والثانــي عنــد الراكــب والثالــث علــى‬\n     ‫الرصيــف فاقتربــت ســيارة املكافحــة التــي كنــت فيهــا ونزلنــا مــن‬\n     ‫الســيارة للقبــض فهــرب أحــد الثالثــة وال أعــرف بالضبــط ألن الوقــت‬\n     ‫ليــل واالثنــان اآلخــران لــم يهربــا وقبــض عليهمــا يف املوقــع وأنــا تبعــت‬\n     ‫الشــخص الهــارب وقبضــت عليــه علــى بعــد خمســمائة متــر تقريبـ ًا داخــل‬\n     ‫احلــي وبتفتيــش الهــارب لــم يعثــر معــه علــى شــيء و ســمعت أنــه عثــر علــى‬\n     ‫حبــة مــع أحدهــم وال أعرفــه بالضبــط ولــم أســمع املكاملــة التــي دارت‬\n     ‫بــن املصــدر واملدعــى عليــه هــذه شــهادتي وبعــرض الشــاهد وشــهادته‬\n     ‫علــى املدعــى عليهمــا احلاضريــن قــاال أمــا الشــاهد فــا نقــول فيــه شــيئ ًا‬\n     ‫وشــهادته صحيحــه عليــه فقــد أفهمــت املدعــي العــام بإحضــار باقــي‬\n\n\n‫‪19‬‬\n\f‫أعضاء الفرقة لسماع شهادتهم ويف جلسة أخرى بتاريخ‪1432/4/16‬هـ‬\n‫حضــر املدعــي العــام واملدعــى عليهــم ونظــر ًا لــورود تعميــم ســمو النائــب‬\n‫الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم(‪ )18749‬بتاريــخ‬\n‫‪1432/3/28‬ه ـ املبنــي علــى األمــر الكــرمي رقــم(أ‪)25/‬‬\n‫وتاريخ‪1432/3/20‬ه ـ املتضمــن إعفــاء الســجناء الســعوديني‬\n‫احملكومــن واملوقوفــن واملطلقــن بالكفالــة يف اجلرائــم غير الكبيرة‬\n‫فقــد رفعــت املعاملــة لطلــب اإلفــادة عــن شــمول هــذه الدعــوى بتعليمــات‬\n‫العفــو كمــا قــررت األمــر باإلفــراج عــن املدعــى عليــه ‪ ..‬بكفالــة‬\n‫حضوريــة ويف جلســة أخــرى بتاريخ‪1433/7/1‬ه ـ افتتحــت اجللســة‬\n‫بحضــور املدعــي العــام و املدعــى عليــه و قــد عــادت املعاملــة بكتــاب‬\n‫ســعادة مديــر مكافحــة املخــدرات بالدمــام برقــم‪5516/1/3/15‬يف‬\n‫‪1433/5/29‬ه ـ وبرفقهــا محاضــر أعضــاء جلنــة العفــو املتضمنــة شــمول‬\n‫العفــو للمدعــى عليهمــا و فجــرى ســؤال املدعــي العــام عــن معدي محضر‬\n‫قبــض فقــال أطلــب مهلــة إلحضــار بقيتهــم ويف جلســة أخــرى‬\n‫بتاريخ‪1433/7/14‬ه ـ حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه أو‬\n‫يبــدي عــذر ًا كمــا حضــر الشــاهد ‪ ........‬ســعودي رقــم ســجله املدنــي‬\n‫(‪ ).....‬وعــرف بنفســه بانــه جنــدي أول بــإدارة مكافحــة املخــدرات‬\n‫بالدمــام وأحــد املوقعــن علــى محضــر القبــض وباستشــهاده قــال أشــهد‬\n‫بأنــه قبــل أكثــر مــن ســنة تبلغنــا عــن طريــق أحــد املصــادر عــن قيــام‬\n‫املدعــى عليــه بترويــج حبــوب الكبتاجــون واســتعد املصــدر بــأن يتعــاون‬\n‫ا قــام باالتصــال علــى بجهــاز جــوال علــى مســمع‬    ‫يف القبــض عليــه وفع ـ ً‬\n‫منــي وطلــب منــه أغــراض مبائــة(‪ )100‬ريــال وســمعت يواعــده عنــد بوفيه‬\n‫بجــوار مجمــع جتــاري يف ال ـ (‪ ).....‬ثــم ذهبــت مــع الفرقــة للمراقبــة مــن‬\n\n\n                                                                                    ‫‪20‬‬\n\f     ‫بعيــد ولــم أذهــب مــع املصــدر وشــاهدت ســيارة املصــدر واقفــة بجــوار‬\n     ‫البوفيــه ولــم أشــاهد تفاصيــل االســتالم أو التســليم وحينمــا أعطيــت لنــا‬\n     ‫اإلشــارة للقبــض كان مــع املتهــم شــخصني آخريــن هربــا ومت القبــض‬\n     ‫عليهمــا جميعـ ًا وال أذكــر التفاصيــل بعــد ذلــك علمـ ًا بأنــه بعــد عودتنــا‬\n     ‫لــإدارة مت مطابقــة الرقــم الــذي اتصــل بــه املصــدر علــى جــوال املقبــوض‬\n     ‫عليــه فتطابقــا هــذه شــهادتي فطلبــت مــن املدعــي العــام مزكيــن‬\n     ‫للشــاهد فأحضــر فشــهد بعدالــة وثقــة الشــاهد وطلــب املدعــي العــام‬\n     ‫مهلــة إلحضــار مزكــي آخــر ويف جلســة أخــرى بتاريخ‪1433/7/20‬ه ـ‬\n     ‫حضــر املدعــي العــام كمــا حضــر املدعــى عليه وبعرض شــهادة الشــاهد‬\n     ‫يف اجللســة املاضيــة عليــه قــال أمــا الشــاهد فــا أعرفــه وال أقــول فيــه‬\n     ‫شــيئ ًا وأمــا شــهادته فمــا ذكــره مــن االتصــال واملواعــدة صحيــح لكنــه‬\n     ‫لــم يطلــب منــي أغــراض‪ .‬كمــا حضــر وشــهد بعدالــة وثقــة الشــاهد‬\n     ‫ســؤال املدعــي العــام ألديــه زيــادة بينــة علــى دعــوى الشــروع يف الترويــج‬\n     ‫والهــروب قــال ليــس لــدي ســوى مــا قدمــت فبنــاء علــى مــا تقــدم وحيــث‬\n     ‫تتلخــص دعــوى املدعــي العــام يف اتهــام املدعــى عليــه بحيــازة حبــة مــن‬\n     ‫احلبــوب املنبهــة احملظــورة بقصــد الترويــج والشــروع يف ترويجهــا وتعاطيه‬\n     ‫لنوعهــا وتســتر املدعــى عليهمــا اآلخريــن علــى املدعــى عليــه وهروبهــم‬\n     ‫جميعـ ًا مــن رجــال الضبــط اجلنائــي والختصــاص هــذه احملكمــة بنظــر‬\n     ‫هــذه الدعــوى بنــاء علــى املــواد(‪ )131،128‬مــن نظام اإلجــراءات اجلزائية‬\n     ‫وإلقــرار املدعــى عليــه باتصــال أحــد األشــخاص بــه علــى هاتفــه ذي‬\n     ‫الرقــم املشــار لــه يف الدعــوى ومواعدتــه لــه يف املــكان الــذي قبــض عليــه‬\n     ‫فيــه وإلقــراره بتعاطــي احلبــوب املنبهــة احملظــورة وبحيــازة حبــة واحــدة‬\n     ‫منهــا ولتظافــر عــدد مــن القرائــن علــى أن احليــازة كانت لغــرض الترويج‬\n\n\n‫‪21‬‬\n\f‫منهــا‪-1 :‬ماتضمنــه محضــر البــاغ املــؤرخ ‪1431/11/1‬ه ـ املــدون علــى‬\n‫ص (‪ )1‬ملــف مرفــق لفــة (‪ )1‬املتضمــن ورود بــاغ عــن قيــام املدعــى عليــه‬\n‫بترويــج حبــوب الكبتاجــون احملظــورة ‪ -2‬مــا تضمنــه محضــر القبــض‬\n‫مــن اتصــال أحــد مصــادر املكافحــة باملدعــى عليــه وطلبــه حبــوب‬\n‫محظــورة ومواعــدة املدعــى عليــه لــه‪ -3 .‬ماجــاء يف أقــوال املدعــى عليــه‬\n‫حتقيقـ ًا مــن إقــراره باتصــال شــخص يريــد حبــوب ومواعدتــه لــه‪ .‬ونظــر ًا‬\n‫لعــدم ثبــوت قيــام املدعــى عليــه باســتالم الثمــن أو تســليم احلبــوب املنبهــة‬\n‫احملظــورة محــل االتفــاق بــل وعــدم العثــور عليهــا معــه ممــا ينتفــي معــه‬\n‫وصــف الشــروع يف ارتــكاب جرميــة الترويــج ‪ ،‬وحصــول املواعــدة‬\n‫ا حتضيري ـ ًا فحســب‬     ‫الهاتفيــة واحلضــور للموقــع املتفــق عليــه يعــد عم ـ ً‬\n‫وليــس شــروع ًا يف ارتــكاب اجلرميــة إذ الشــروع يســتلزم ارتــكاب فعــل‬\n‫يعتبــر يف ذاتــه جــزء ًا مــن األجــزاء املكونــة للركــن املــادي للجرميــة وهــو‬\n‫االســتالم والتســليم أو يــؤدي إليهــا حــا ًال ومباشــرة وهــذا مالــم يحصــل‬\n‫ولعــدم إقامــة املدعــي العــام بينــة موصلــة علــى دعــوى الهــروب التــي‬\n‫أنكرهــا املدعــى عليــه وأكــد ذلــك مــا جــاء يف شــهادة عضــو الفرقــة‬\n‫أمــام هــذه احملكمــة ونظــر ًا ألن مــا أقــدم عليــه املتهــم مــن تعاطي احلبوب‬\n‫املنبهــة احملظــورة وحيازتهــا فعــل محــرم شــرع ًا ملــا تســببه هــذه احلبــوب‬\n‫مــن أضــرار صحيــة بالغــة واهلل تعالــى يقــول (( وال تلقــوا بأيديكــم إلــى‬\n‫التهلكــة )) البقــرة اآليــة‪ 195:‬كمــا أنــه فعــل مجــرم وفقـ ًا للمادة(‪)3‬مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لهــذا كلــه فقــد ثبــت‬\n‫لــدي إدانــة املدعــى عليــه احلاضــر باآلتــي‪ :‬أوالً‪ :‬تعاطــي احلبــوب املنبهــة‬\n‫احملظــورة‪ .‬ثاني ـاً‪ :‬حيــازة حبــة واحــدة مــن احلبــوب املنبهــة احملظــورة‬\n‫بقصــد الترويــج مبقابــل و نظــر ًا لقلــة الكميــة احملــازة وعــدم وجــود‬\n\n\n                                                                                       ‫‪22‬‬\n\f     ‫ســوابق علــى املدعــى عليــه وبنــاء علــى املواد(‪)38،60،56،53‬مــن نظــام‬\n     ‫مكافحــة املخــدرات فقــد حكمــت عليــه باآلتــي‪ :‬أوال‪ :‬جلــده ســتني‬\n     ‫جلــدة دفعــة واحــدة تعزيــر ًا علــى التعاطــي‪ .‬ثاني ـاً‪ :‬تغرميــه ألــف ريــال‬\n     ‫وســجنه ســتة أشــهر ومصــادرة هاتفــه اجلــوال ذي الرقــم املصنعــي (‪).....‬‬\n     ‫والشــريحة وعــدم صرفهــا لــه مــرة أخــرى ومنعــه مــن الســفر خــارج‬\n     ‫اململكــة مــدة ســنتني تعزيــر ًا لــه علــى احليــازة‪ .‬ورددت طلــب املدعــي‬\n     ‫العــام معاقبــة املدعــى عليــه علــى الشــروع يف الترويــج والهــروب مــن رجال‬\n     ‫األمــن لعــدم ثبوتهــا كمــا رددت طلــب معاقبــة املدعــى عليهمــا النقضــاء‬\n     ‫الدعــوى بحقهــا بعفــو ولــي األمــر وذلــك وفق ـ ًا للمادة(‪)22‬مــن نظــام‬\n     ‫اإلجــراءات اجلزائيــة وبإعــان احلكــم قنــع بــه املدعــى عليه وقــرر املدعي‬\n     ‫العــام اعتراضــه وطلــب رفــع املعاملــة حملكمــة االســتئناف دون تقــدمي‬\n     ‫الئحــة‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد‬\n     ‫هلل وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n     ‫الشــرقية وبرفقهــا القــرار رقم‪33432328‬يف‪1433/10/21‬هـ املتضمن‪:‬‬\n     ‫لوحــظ أن فضيلتــه أثبــت إدانــة املدعــى عليــه بحيــازة حبــة واحــدة مــن‬\n     ‫احلبــوب احملظــورة لقصــد الترويــج مبقابــل واملدعــى عليــه منكــر ملــا‬\n     ‫أثبتــه فضيلتــه حيــث أن مــا قدمــه املدعــي العــام مــن بينــة ال يكفــي‬\n     ‫إلثبــات مــا حكــم بــه فضيلتــه أ‪ .‬هــ‪ .‬فأجيــب أصحــاب الفضيلــة بــأن‬\n     ‫املدعــى عليــه وإن أنكــر قصــد الترويــج إال أن قرائــن عديــدة جعلــت‬\n     ‫احملكمــة تطمئــن إلــى مــا توصلــت إليــه يف احلكــم مــن أن احليــازة‬\n     ‫كانــت لغــرض الترويــج فاملدعــى عليــه أقــر حتقيقـ ًا باتصــال املصــدر بــه‬\n     ‫لطلــب حبــوب وأنــه قــال عنــدي وطلــب منــه احلضــور يف املــكان الــذي‬\n     ‫قبــض عليــه فيــه كمــا أن شــهادة عضــو املكافحــة تؤكــد ذلــك وقــد‬\n\n\n‫‪23‬‬\n\f‫عثــر مــع املدعــى عليــه يف املوقــع املتفــق عليــه علــى إحــدى هــذه احلبــوب‬\n‫وال يخفــى علــى أصحــاب الفضيلــة أن للقاضــي ســلطة تقديريــة يف تقدير‬\n‫ثبــوت األدلــة ونظــر ًا لقناعــة املدعــى عليــه باحلكــم فلــم يظهــر لــي مــا‬\n‫يوجــب العــدول عمــا حكمــت بــه وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫الــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد فلــدي أنــا رئيــس احملكمــة‬\n‫اجلزائيــة مبحافظــة القطيــف فقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار رقــم ‪ 349325‬يف‬\n‫‪1434/1/12‬ه ـ املتضمــن املصادقــة علــى احلكــم بعــد اإليضــاح األخيــر‬\n                                             ‫و للبيان أحلق يف ‪1434/2/3‬هـ‪.‬‬\n\n\n\n\n                                                                                     ‫‪24‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":13,"source_page_end":24,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5706aad6fbcb1351344c20ca8f59be512d60dac0c1de80c641a5bf303a4e28e0","normalized_text_hash":"e1c225a1d3cb0aa712f0e590763022bd138f9013f234392df72ae8acb3a7f4bf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p13-33354788"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

